insert into public.exams(slug,title,source,year) values ('unesp-2026-fase1','Unesp 2026 · 1ª fase · Versão 1','unesp','2026') on conflict(slug) do update set title=excluded.title;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,1,'Conhecimentos Gerais','Para responder às questões de 01 a 05, leia um trecho do romance ilustrado As aventuras de Nhô Quim: ou impressões de uma viagem à Corte, de Angelo Agostini (1843-1910) e Cândido Aragonez de Faria (1849-1911), publicado originalmente entre 30 de janeiro de 1869 e 12 de outubro de 1872. O Dia do Quadrinho Nacional é celebrado em 30 de janeiro em razão justamente da data de publicação do primeiro capítulo desse romance ilustrado. Nhô1 Quim, jovem de vinte anos, filho único de gente rica porém honrada, namorara-se de sinhá Rosa, moça virtuosa, mas que... de louça nem um pires. O velho Quim, tendo só em vista a felicidade do pequeno, entende que mulher sem dinheiro é asneira; e por isso em lugar de mandar o filho plantar batatas, (o que seria muito proveitoso na roça), resolve-o a dar um passeio à Corte para distraí-lo. (Angelo Agostini e Cândido Aragonez de Faria. As aventuras do Nhô Quim: ou impressões de uma viagem à Corte, 2024. Adaptado.) 1 nhô: tratamento reverente dispensado originalmente aos brancos, especialmente aos patrões ou proprietários, pelos escravizados. 2 ruço: pelo castanho-claro. 3 selim: sela para montaria. 4 ratão: indivíduo excêntrico, extravagante. 5 caiporismo: estado, condição ou qualidade de quem é caipora, infeliz ou azarado em tudo ou quase tudo que faz ou que lhe sucede. Depreende-se do início do romance ilustrado que a viagem de Nhô Quim à Corte se deve',null,'{"original": ["/unesp-2026/q01-1.png"], "support": ["/unesp-2026/contexto-1-5-1.png"]}','["ao seu receio de ter que se casar com uma mulher de índole duvidosa.", "à sua falta de habilidade com as atividades agrícolas.", "à sua falta de interesse pelos negócios do pai na roça.", "à sua desconfiança de que a namorada estaria interessa- da apenas em ascender socialmente.", "ao seu envolvimento com uma mulher pertencente a um estrato social inferior."]'::jsonb,'E',null from public.exams where slug='unesp-2026-fase1' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,2,'Conhecimentos Gerais','Para responder às questões de 01 a 05, leia um trecho do romance ilustrado As aventuras de Nhô Quim: ou impressões de uma viagem à Corte, de Angelo Agostini (1843-1910) e Cândido Aragonez de Faria (1849-1911), publicado originalmente entre 30 de janeiro de 1869 e 12 de outubro de 1872. O Dia do Quadrinho Nacional é celebrado em 30 de janeiro em razão justamente da data de publicação do primeiro capítulo desse romance ilustrado. Nhô1 Quim, jovem de vinte anos, filho único de gente rica porém honrada, namorara-se de sinhá Rosa, moça virtuosa, mas que... de louça nem um pires. O velho Quim, tendo só em vista a felicidade do pequeno, entende que mulher sem dinheiro é asneira; e por isso em lugar de mandar o filho plantar batatas, (o que seria muito proveitoso na roça), resolve-o a dar um passeio à Corte para distraí-lo. (Angelo Agostini e Cândido Aragonez de Faria. As aventuras do Nhô Quim: ou impressões de uma viagem à Corte, 2024. Adaptado.) 1 nhô: tratamento reverente dispensado originalmente aos brancos, especialmente aos patrões ou proprietários, pelos escravizados. 2 ruço: pelo castanho-claro. 3 selim: sela para montaria. 4 ratão: indivíduo excêntrico, extravagante. 5 caiporismo: estado, condição ou qualidade de quem é caipora, infeliz ou azarado em tudo ou quase tudo que faz ou que lhe sucede. Com finalidade humorística, o narrador explora abertamente a contraposição do sentido figurado e do sentido literal de uma expressão no trecho:',null,'{"original": ["/unesp-2026/q02-1.png"], "support": ["/unesp-2026/contexto-1-5-1.png"]}','["“por isso em lugar de mandar o filho plantar batatas, (o que seria muito proveitoso na roça), resolve-o a dar um passeio à Corte para distraí-lo”.", "“oferecendo um pedaço de queijo de Minas, que traz bem guardadinho na bota, e que pelo aroma parece queijo suíço”.", "“Logo que sofre o primeiro encontrão, Nhô Quim acha que esta gente da Corte é bem malcriada e que nem se- quer pede licença para passar ”.", "“Nhô Quim, jovem de vinte anos, filho único de gente rica porém honrada, namorara-se de sinhá Rosa, moça virtuosa, mas que... de louça nem um pires”.", "“Pelo sim pelo não o nosso homem benze-se três vezes antes de entrar no trem”."]'::jsonb,'A',null from public.exams where slug='unesp-2026-fase1' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,3,'Conhecimentos Gerais','Para responder às questões de 01 a 05, leia um trecho do romance ilustrado As aventuras de Nhô Quim: ou impressões de uma viagem à Corte, de Angelo Agostini (1843-1910) e Cândido Aragonez de Faria (1849-1911), publicado originalmente entre 30 de janeiro de 1869 e 12 de outubro de 1872. O Dia do Quadrinho Nacional é celebrado em 30 de janeiro em razão justamente da data de publicação do primeiro capítulo desse romance ilustrado. Nhô1 Quim, jovem de vinte anos, filho único de gente rica porém honrada, namorara-se de sinhá Rosa, moça virtuosa, mas que... de louça nem um pires. O velho Quim, tendo só em vista a felicidade do pequeno, entende que mulher sem dinheiro é asneira; e por isso em lugar de mandar o filho plantar batatas, (o que seria muito proveitoso na roça), resolve-o a dar um passeio à Corte para distraí-lo. (Angelo Agostini e Cândido Aragonez de Faria. As aventuras do Nhô Quim: ou impressões de uma viagem à Corte, 2024. Adaptado.) 1 nhô: tratamento reverente dispensado originalmente aos brancos, especialmente aos patrões ou proprietários, pelos escravizados. 2 ruço: pelo castanho-claro. 3 selim: sela para montaria. 4 ratão: indivíduo excêntrico, extravagante. 5 caiporismo: estado, condição ou qualidade de quem é caipora, infeliz ou azarado em tudo ou quase tudo que faz ou que lhe sucede. Considerando o contexto histórico-social de produção do romance ilustrado, depreende-se que Nhô Quim viajou para a seguinte cidade:',null,'{"original": ["/unesp-2026/q03-1.png"], "support": ["/unesp-2026/contexto-1-5-1.png"]}','["Paraty.", "São Paulo.", "Rio de Janeiro.", "Salvador.", "Ouro Preto."]'::jsonb,'C',null from public.exams where slug='unesp-2026-fase1' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,4,'Conhecimentos Gerais','Para responder às questões de 01 a 05, leia um trecho do romance ilustrado As aventuras de Nhô Quim: ou impressões de uma viagem à Corte, de Angelo Agostini (1843-1910) e Cândido Aragonez de Faria (1849-1911), publicado originalmente entre 30 de janeiro de 1869 e 12 de outubro de 1872. O Dia do Quadrinho Nacional é celebrado em 30 de janeiro em razão justamente da data de publicação do primeiro capítulo desse romance ilustrado. Nhô1 Quim, jovem de vinte anos, filho único de gente rica porém honrada, namorara-se de sinhá Rosa, moça virtuosa, mas que... de louça nem um pires. O velho Quim, tendo só em vista a felicidade do pequeno, entende que mulher sem dinheiro é asneira; e por isso em lugar de mandar o filho plantar batatas, (o que seria muito proveitoso na roça), resolve-o a dar um passeio à Corte para distraí-lo. (Angelo Agostini e Cândido Aragonez de Faria. As aventuras do Nhô Quim: ou impressões de uma viagem à Corte, 2024. Adaptado.) 1 nhô: tratamento reverente dispensado originalmente aos brancos, especialmente aos patrões ou proprietários, pelos escravizados. 2 ruço: pelo castanho-claro. 3 selim: sela para montaria. 4 ratão: indivíduo excêntrico, extravagante. 5 caiporismo: estado, condição ou qualidade de quem é caipora, infeliz ou azarado em tudo ou quase tudo que faz ou que lhe sucede. O estilo cômico e satírico observado em As aventuras de Nhô Quim caracteriza também a seguinte obra do Romantismo brasileiro:',null,'{"original": ["/unesp-2026/q04-1.png"], "support": ["/unesp-2026/contexto-1-5-1.png"]}','["O cortiço, de Aluísio Azevedo.", "Memórias de um sargento de milícias, de Manuel Antônio de Almeida.", "Memórias póstumas de Brás Cubas, de Machado de Assis.", "Iracema, de José de Alencar.", "Macunaíma, de Mário de Andrade."]'::jsonb,'B',null from public.exams where slug='unesp-2026-fase1' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,5,'Conhecimentos Gerais','Para responder às questões de 01 a 05, leia um trecho do romance ilustrado As aventuras de Nhô Quim: ou impressões de uma viagem à Corte, de Angelo Agostini (1843-1910) e Cândido Aragonez de Faria (1849-1911), publicado originalmente entre 30 de janeiro de 1869 e 12 de outubro de 1872. O Dia do Quadrinho Nacional é celebrado em 30 de janeiro em razão justamente da data de publicação do primeiro capítulo desse romance ilustrado. Nhô1 Quim, jovem de vinte anos, filho único de gente rica porém honrada, namorara-se de sinhá Rosa, moça virtuosa, mas que... de louça nem um pires. O velho Quim, tendo só em vista a felicidade do pequeno, entende que mulher sem dinheiro é asneira; e por isso em lugar de mandar o filho plantar batatas, (o que seria muito proveitoso na roça), resolve-o a dar um passeio à Corte para distraí-lo. (Angelo Agostini e Cândido Aragonez de Faria. As aventuras do Nhô Quim: ou impressões de uma viagem à Corte, 2024. Adaptado.) 1 nhô: tratamento reverente dispensado originalmente aos brancos, especialmente aos patrões ou proprietários, pelos escravizados. 2 ruço: pelo castanho-claro. 3 selim: sela para montaria. 4 ratão: indivíduo excêntrico, extravagante. 5 caiporismo: estado, condição ou qualidade de quem é caipora, infeliz ou azarado em tudo ou quase tudo que faz ou que lhe sucede. “Encostando-se à vidraça do Grande Mágico, Nhô Quim sentiu uma coisa!...” Em relação à oração que a sucede, a oração sublinhada expressa ideia de',null,'{"original": ["/unesp-2026/q05-1.png"], "support": ["/unesp-2026/contexto-1-5-1.png"]}','["conclusão.", "finalidade.", "consequência.", "tempo.", "condição."]'::jsonb,'D',null from public.exams where slug='unesp-2026-fase1' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,6,'Conhecimentos Gerais','Examine a tirinha da cartunista Laerte, publicada em sua conta @laerteminotaura no Instagram em 29.12.2022. Na construção do sentido de sua tirinha, Laerte explora basicamente',null,'{"original": ["/unesp-2026/q06-1.png"], "support": []}','["uma hipérbole que, por sua vez, se desdobra em outras hipérboles numa progressão aritmética de razão 1.", "uma hipérbole que, por sua vez, se desdobra em outras hipérboles numa progressão aritmética de razão 2.", "um paradoxo que, por sua vez, se desdobra em outros paradoxos numa progressão geométrica de razão 2.", "uma antítese que, por sua vez, se desdobra em outras antíteses numa progressão geométrica de razão 1.", "uma antítese que, por sua vez, se desdobra em outras antíteses numa progressão geométrica de razão 2."]'::jsonb,'E',null from public.exams where slug='unesp-2026-fase1' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,7,'Conhecimentos Gerais','Para responder às questões de 07 a 11, leia o primeiro poema da seção intitulada “Homenagem a Ricardo Reis”, da poeta portuguesa Sophia de Mello Breyner Andresen (1919-2004), publicado originalmente em 1972 no livro Dual. Não creias, Lídia, que nenhum estio1 Por nós perdido possa regressar Oferecendo a flor Que adiamos colher. Cada dia te é dado uma só vez E no redondo círculo da noite Não existe piedade Para aquele que hesita. Mais tarde será tarde e já é tarde. O tempo apaga tudo menos esse Longo indelével rasto2 Que o não-vivido deixa. Não creias na demora em que te medes. Jamais se detém Kronos3 cujo passo Vai sempre mais à frente Do que o teu próprio passo. (Sophia de Mello Breyner Andresen. Coral e outros poemas, 2018.) 1 estio: verão. 2 rasto: rastro. 3 Kronos: do grego khrónos, “tempo”. Na mitologia grega, titã do tempo. Logo na estrofe inicial do poema, o eu lírico ressalta o caráter',null,'{"original": ["/unesp-2026/q07-1.png"], "support": ["/unesp-2026/contexto-7-11-1.png"]}','["desumano do mundo.", "insondável da vida.", "irreversível do tempo.", "enigmático do mundo.", "imprevisível do tempo."]'::jsonb,'C',null from public.exams where slug='unesp-2026-fase1' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,8,'Conhecimentos Gerais','Para responder às questões de 07 a 11, leia o primeiro poema da seção intitulada “Homenagem a Ricardo Reis”, da poeta portuguesa Sophia de Mello Breyner Andresen (1919-2004), publicado originalmente em 1972 no livro Dual. Não creias, Lídia, que nenhum estio1 Por nós perdido possa regressar Oferecendo a flor Que adiamos colher. Cada dia te é dado uma só vez E no redondo círculo da noite Não existe piedade Para aquele que hesita. Mais tarde será tarde e já é tarde. O tempo apaga tudo menos esse Longo indelével rasto2 Que o não-vivido deixa. Não creias na demora em que te medes. Jamais se detém Kronos3 cujo passo Vai sempre mais à frente Do que o teu próprio passo. (Sophia de Mello Breyner Andresen. Coral e outros poemas, 2018.) 1 estio: verão. 2 rasto: rastro. 3 Kronos: do grego khrónos, “tempo”. Na mitologia grega, titã do tempo. “O tempo apaga tudo menos esse Longo indelével rasto Que o não-vivido deixa.” (3a estrofe) Depreende-se desses versos que',null,'{"original": ["/unesp-2026/q08-1.png"], "support": ["/unesp-2026/contexto-7-11-1.png"]}','["o que entendemos por tempo é uma construção subjetiva.", "o tempo é incapaz de apagar nossas vivências mais íntimas.", "o que não foi vivido está sujeito a se perder com o tempo.", "o que entendemos por tempo é uma construção social.", "o que não foi vivido não pode ser apagado pelo tempo."]'::jsonb,'E',null from public.exams where slug='unesp-2026-fase1' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,9,'Conhecimentos Gerais','Para responder às questões de 07 a 11, leia o primeiro poema da seção intitulada “Homenagem a Ricardo Reis”, da poeta portuguesa Sophia de Mello Breyner Andresen (1919-2004), publicado originalmente em 1972 no livro Dual. Não creias, Lídia, que nenhum estio1 Por nós perdido possa regressar Oferecendo a flor Que adiamos colher. Cada dia te é dado uma só vez E no redondo círculo da noite Não existe piedade Para aquele que hesita. Mais tarde será tarde e já é tarde. O tempo apaga tudo menos esse Longo indelével rasto2 Que o não-vivido deixa. Não creias na demora em que te medes. Jamais se detém Kronos3 cujo passo Vai sempre mais à frente Do que o teu próprio passo. (Sophia de Mello Breyner Andresen. Coral e outros poemas, 2018.) 1 estio: verão. 2 rasto: rastro. 3 Kronos: do grego khrónos, “tempo”. Na mitologia grega, titã do tempo. Conforme sugerido pelo próprio título da seção, trata-se de um poema escrito à maneira de Ricardo Reis, o heterônimo neoclássico do poeta Fernando Pessoa (1888-1935). A exemplo do que ocorre com frequência na poética de Ricardo Reis, o eu lírico configura aqui o seguinte tópico clássico:',null,'{"original": ["/unesp-2026/q09-1.png"], "support": ["/unesp-2026/contexto-7-11-1.png"]}','["locus horrendus (“lugar horrível”).", "inutilia truncat (“corta o inútil”).", "carpe diem (“aproveita o momento”).", "locus amoenus (“lugar aprazível”).", "fugere urbem (“fugir da cidade”)."]'::jsonb,'C',null from public.exams where slug='unesp-2026-fase1' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,10,'Conhecimentos Gerais','Para responder às questões de 07 a 11, leia o primeiro poema da seção intitulada “Homenagem a Ricardo Reis”, da poeta portuguesa Sophia de Mello Breyner Andresen (1919-2004), publicado originalmente em 1972 no livro Dual. Não creias, Lídia, que nenhum estio1 Por nós perdido possa regressar Oferecendo a flor Que adiamos colher. Cada dia te é dado uma só vez E no redondo círculo da noite Não existe piedade Para aquele que hesita. Mais tarde será tarde e já é tarde. O tempo apaga tudo menos esse Longo indelével rasto2 Que o não-vivido deixa. Não creias na demora em que te medes. Jamais se detém Kronos3 cujo passo Vai sempre mais à frente Do que o teu próprio passo. (Sophia de Mello Breyner Andresen. Coral e outros poemas, 2018.) 1 estio: verão. 2 rasto: rastro. 3 Kronos: do grego khrónos, “tempo”. Na mitologia grega, titã do tempo. Depreende-se das reflexões do eu lírico uma visão de mundo influenciada, sobretudo, pela',null,'{"original": ["/unesp-2026/q10-1.png"], "support": ["/unesp-2026/contexto-7-11-1.png"]}','["filosofia iluminista.", "teoria de Marx.", "teoria de Darwin.", "filosofia de Epicuro.", "filosofia de Platão."]'::jsonb,'D',null from public.exams where slug='unesp-2026-fase1' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,11,'Conhecimentos Gerais','Para responder às questões de 07 a 11, leia o primeiro poema da seção intitulada “Homenagem a Ricardo Reis”, da poeta portuguesa Sophia de Mello Breyner Andresen (1919-2004), publicado originalmente em 1972 no livro Dual. Não creias, Lídia, que nenhum estio1 Por nós perdido possa regressar Oferecendo a flor Que adiamos colher. Cada dia te é dado uma só vez E no redondo círculo da noite Não existe piedade Para aquele que hesita. Mais tarde será tarde e já é tarde. O tempo apaga tudo menos esse Longo indelével rasto2 Que o não-vivido deixa. Não creias na demora em que te medes. Jamais se detém Kronos3 cujo passo Vai sempre mais à frente Do que o teu próprio passo. (Sophia de Mello Breyner Andresen. Coral e outros poemas, 2018.) 1 estio: verão. 2 rasto: rastro. 3 Kronos: do grego khrónos, “tempo”. Na mitologia grega, titã do tempo. Com a intenção de obter maior expressividade, o eu lírico lança mão de uma construção pleonástica no seguinte verso:',null,'{"original": ["/unesp-2026/q11-1.png"], "support": ["/unesp-2026/contexto-7-11-1.png"]}','["“E no redondo círculo da noite” (2a estrofe)", "“Por nós perdido possa regressar” (1a estrofe)", "“Para aquele que hesita.” (2a estrofe)", "“O tempo apaga tudo menos esse” (3a estrofe)", "“Não creias na demora em que te medes.” (4a estrofe)"]'::jsonb,'A',null from public.exams where slug='unesp-2026-fase1' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,12,'Conhecimentos Gerais','Examine o post publicado pela comunidade “The Language Nerds” em sua conta no Facebook em 01.09.2019. If you laugh, you probably have no friends Estereótipo é uma generalização simplificada e preconcebida, que reduz a complexidade de indivíduos a características padronizadas, com base em ideias repetidas sobre determinado grupo. O post explora o estereótipo de que',null,'{"original": ["/unesp-2026/q12-1.png"], "support": []}','["pessoas muito arrogantes não têm amigos, já que são ca- pazes de usar materiais químico-físicos fora do contexto laboratorial para demonstrar superioridade intelectual.", "pessoas muito inteligentes não têm amigos, já que são capazes de compreender um tipo de humor restrito a quem domina o conhecimento físico de reflexão luminosa.", "pessoas ardilosas não têm amigos, já que são capazes de construir armadilhas no ambiente escolar a partir de seu conhecimento químico de composto orgânico.", "pessoas muito inteligentes não têm amigos, já que são ca- pazes de compreender um tipo de humor restrito a quem domina o conhecimento químico de estrutura molecular.", "pessoas ardilosas não têm amigos, já que são capazes de construir armadilhas no ambiente escolar a partir de seu conhecimento físico de comportamento dos fluidos."]'::jsonb,'D',null from public.exams where slug='unesp-2026-fase1' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,13,'Conhecimentos Gerais','Para responder às questões de 13 a 17, leia o início do ensaio “Bom dia, senhor Courbet!” do crítico de arte Jorge Coli (1947- ). Gustave Courbet (1819-1877) e sua obra revelam uma relação intrincada entre aquilo que é subjetivo e aquilo que é coletivo; entre aquilo que é biografia individual e aquilo que é pintura propriamente dita. Não se trata de uma obra, à primeira vista, sedutora. Ao contrário, ela elimina o fascínio mais imediato — o fascínio das belas cores, por exemplo; o fascínio dos temas, torturados ou felizes. Contraditória com o modo de ser do artista — que era truculento, tagarela, escandaloso, barulhento —, essa obra é grave e silenciosa. Ela exige recolhimento, meditação, ela exige a frequentação persistente, ela exige o olhar prolongado. Os quadros de Courbet dão a impressão de conterem elementos destinados a afugentar o olhar superficial e mesmo, algumas vezes, a horrorizá-lo. Mas essa obra e seu autor, de modo cúmplice, promoveram o desgarramento dos vínculos que submetiam os artistas a valores que estavam constituídos fora deles. Até Courbet, os artistas dependiam de um universo ético que estavam encarregados de veicular — por exemplo, Jacques-Louis David (1748-1825) celebra a Revolução Francesa, ou celebra o Império napoleônico; Eugène Delacroix (1798-1863) tratará de temas que envolvem a liberdade política. O que nós assistimos com a arte de Courbet é ao seu afastamento desses critérios externos que possuem valores já constituídos, e ao estabelecimento, para o artista, de um lugar que é independente e que lhe é próprio: este lugar é o da marginalidade. Courbet circunscreve pela primeira vez o campo da marginalidade, e o define como um território de eleição, um território privilegiado em relação ao dos outros homens. O artista marginal é aquele que não deve mais nada nem ao mundo, nem a ninguém — a não ser a si próprio. Ao mesmo tempo independente e consciente da elevação de sua tarefa artística, é obrigado, para manter-se à altura de si mesmo, a estabelecer os seus próprios valores. Isto é, ele é obrigado a construir uma ética para si. (https://artepensamento.ims.com.br, 1992. Adaptado.) De acordo com Jorge Coli, a obra de Courbet, em contradição com o modo de ser do artista, caracteriza-se',null,'{"original": ["/unesp-2026/q13-1.png"], "support": ["/unesp-2026/contexto-13-17-1.png"]}','["pela eloquência.", "pela discrição.", "pelo escárnio.", "pelo rebuscamento.", "pela combatividade."]'::jsonb,'B',null from public.exams where slug='unesp-2026-fase1' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
