insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,21,'Conhecimentos Gerais','Leia o texto e examine o gráfico para responder às questões de 21 a 26. The first Game Developers Conference, in 1988, attracted 25 participants and took place in a programmer’s sitting room in California. This 2023 summit, which began on March 20 in a giant exhibition centre in San Francisco, demonstrates how the industry has grown. Some 3.2 billion people now play, thanks largely to the spread of the smartphone. Women are now almost as likely as men to call themselves gamers. Gaming is catching on among all age groups. In Britain, for instance, half of those aged 55-64 play video games, though for less time than the young. Worldwide there are now more console owners aged 35-44 than 16-24. The bigger the audience, the bigger the market. Consumers will spend 185 billion dollars on games in 2023, more than half on mobile games. That is about five times the value of the cinema box office, and two-thirds more than the video-streaming business. As gaming continues to grow, it is beginning to rival television as the world’s favourite entertainment medium. (https://view.e.economist.com, 20.03.2023. Adaptado.) The text and the graph are mainly about the',null,'{"original": ["/unesp-2024/q21-1.png"], "support": ["/unesp-2024/contexto-21-26-1.png"]}','["decline of cinema and music compared to gaming.", "widespread use of smartphones to access video streaming.", "most popular entertainment media among age groups in the world.", "expansion of gaming both as entertainment and business.", "unexpected addiction of aging people to games."]'::jsonb,'D',null from public.exams where slug='unesp-2024-fase1' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,22,'Conhecimentos Gerais','Leia o texto e examine o gráfico para responder às questões de 21 a 26. The first Game Developers Conference, in 1988, attracted 25 participants and took place in a programmer’s sitting room in California. This 2023 summit, which began on March 20 in a giant exhibition centre in San Francisco, demonstrates how the industry has grown. Some 3.2 billion people now play, thanks largely to the spread of the smartphone. Women are now almost as likely as men to call themselves gamers. Gaming is catching on among all age groups. In Britain, for instance, half of those aged 55-64 play video games, though for less time than the young. Worldwide there are now more console owners aged 35-44 than 16-24. The bigger the audience, the bigger the market. Consumers will spend 185 billion dollars on games in 2023, more than half on mobile games. That is about five times the value of the cinema box office, and two-thirds more than the video-streaming business. As gaming continues to grow, it is beginning to rival television as the world’s favourite entertainment medium. (https://view.e.economist.com, 20.03.2023. Adaptado.) According to the first paragraph, the Game Developers Conference growth from 1988 to 2023 can be evaluated by the',null,'{"original": ["/unesp-2024/q22-1.png"], "support": ["/unesp-2024/contexto-21-26-1.png"]}','["premises of both events.", "number of male gamers.", "size of the city that hosted both events.", "inclusion of women and children as game developers.", "3.2 billion people expected to attend the 2023 event."]'::jsonb,'A',null from public.exams where slug='unesp-2024-fase1' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,23,'Conhecimentos Gerais','Leia o texto e examine o gráfico para responder às questões de 21 a 26. The first Game Developers Conference, in 1988, attracted 25 participants and took place in a programmer’s sitting room in California. This 2023 summit, which began on March 20 in a giant exhibition centre in San Francisco, demonstrates how the industry has grown. Some 3.2 billion people now play, thanks largely to the spread of the smartphone. Women are now almost as likely as men to call themselves gamers. Gaming is catching on among all age groups. In Britain, for instance, half of those aged 55-64 play video games, though for less time than the young. Worldwide there are now more console owners aged 35-44 than 16-24. The bigger the audience, the bigger the market. Consumers will spend 185 billion dollars on games in 2023, more than half on mobile games. That is about five times the value of the cinema box office, and two-thirds more than the video-streaming business. As gaming continues to grow, it is beginning to rival television as the world’s favourite entertainment medium. (https://view.e.economist.com, 20.03.2023. Adaptado.) No trecho do primeiro parágrafo “though for less time than the young”, o termo sublinhado introduz, em relação à frase anterior,',null,'{"original": ["/unesp-2024/q23-1.png"], "support": ["/unesp-2024/contexto-21-26-1.png"]}','["uma ressalva.", "um motivo.", "uma previsão.", "uma decorrência.", "uma alternativa."]'::jsonb,'A',null from public.exams where slug='unesp-2024-fase1' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,24,'Conhecimentos Gerais','Leia o texto e examine o gráfico para responder às questões de 21 a 26. The first Game Developers Conference, in 1988, attracted 25 participants and took place in a programmer’s sitting room in California. This 2023 summit, which began on March 20 in a giant exhibition centre in San Francisco, demonstrates how the industry has grown. Some 3.2 billion people now play, thanks largely to the spread of the smartphone. Women are now almost as likely as men to call themselves gamers. Gaming is catching on among all age groups. In Britain, for instance, half of those aged 55-64 play video games, though for less time than the young. Worldwide there are now more console owners aged 35-44 than 16-24. The bigger the audience, the bigger the market. Consumers will spend 185 billion dollars on games in 2023, more than half on mobile games. That is about five times the value of the cinema box office, and two-thirds more than the video-streaming business. As gaming continues to grow, it is beginning to rival television as the world’s favourite entertainment medium. (https://view.e.economist.com, 20.03.2023. Adaptado.) Uma interpretação matemática plausível da frase do segundo parágrafo “The bigger the audience, the bigger the market”, considerando o público e o mercado de games, é de',null,'{"original": ["/unesp-2024/q24-1.png"], "support": ["/unesp-2024/contexto-21-26-1.png"]}','["proporcionalidade inversa entre duas grandezas.", "proporcionalidade direta entre duas grandezas.", "intersecção de dois conjuntos de dados.", "decrescimento quadrático.", "decrescimento exponencial."]'::jsonb,'B',null from public.exams where slug='unesp-2024-fase1' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
