=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,26,'Conhecimentos Gerais','Leia o texto e examine o gráfico para responder às questões de 21 a 26. The first Game Developers Conference, in 1988, attracted 25 participants and took place in a programmer’s sitting room in California. This 2023 summit, which began on March 20 in a giant exhibition centre in San Francisco, demonstrates how the industry has grown. Some 3.2 billion people now play, thanks largely to the spread of the smartphone. Women are now almost as likely as men to call themselves gamers. Gaming is catching on among all age groups. In Britain, for instance, half of those aged 55-64 play video games, though for less time than the young. Worldwide there are now more console owners aged 35-44 than 16-24. The bigger the audience, the bigger the market. Consumers will spend 185 billion dollars on games in 2023, more than half on mobile games. That is about five times the value of the cinema box office, and two-thirds more than the video-streaming business. As gaming continues to grow, it is beginning to rival television as the world’s favourite entertainment medium. (https://view.e.economist.com, 20.03.2023. Adaptado.) No trecho do segundo parágrafo “As gaming continues to grow, it is beginning to rival television as the world’s favourite entertainment medium”, os termos sublinhados equivalem, em português, respectivamente, a',null,'{"original": ["/unesp-2024/q26-1.png"], "support": ["/unesp-2024/contexto-21-26-1.png"]}','["se / tal qual.", "quando / por exemplo.", "à medida que / como.", "porque / exceto.", "do mesmo modo que / de acordo com."]'::jsonb,'C',null from public.exams where slug='unesp-2024-fase1' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,27,'Conhecimentos Gerais','Leia a tira de Bill Amend para responder às questões de 27 a 29. (www.pressthebuttons.com) From the comic strip, one can say that',null,'{"original": ["/unesp-2024/q27-1.png"], "support": ["/unesp-2024/contexto-27-29-1.png"]}','["there is a generation conflict between mother and son.", "Eileen Jacobson and the boy are not friends anymore.", "the final level of the game is the boy’s target before going to school.", "the ice cream is the boy’s prize for winning the game.", "games exert an irresistible attraction on the boy."]'::jsonb,'E',null from public.exams where slug='unesp-2024-fase1' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,28,'Conhecimentos Gerais','Leia a tira de Bill Amend para responder às questões de 27 a 29. (www.pressthebuttons.com) No primeiro quadrinho, a fala “Is she out of her mind?!” indica que o menino',null,'{"original": ["/unesp-2024/q28-1.png"], "support": ["/unesp-2024/contexto-27-29-1.png"]}','["tomará sorvete após ter ido à escola.", "quer se reconciliar com Eileen após uma briga.", "acha que Eileen e a mãe querem agradá-lo.", "considera que a mãe está interferindo na amizade com Eileen.", "ficou irritado com o convite de Eileen."]'::jsonb,'E',null from public.exams where slug='unesp-2024-fase1' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,29,'Conhecimentos Gerais','Leia a tira de Bill Amend para responder às questões de 27 a 29. (www.pressthebuttons.com) No terceiro quadrinho, o termo “that” refere-se a',null,'{"original": ["/unesp-2024/q29-1.png"], "support": ["/unesp-2024/contexto-27-29-1.png"]}','["“the world of warquest expansion”.", "“school, fire or hospitalization”.", "“not moving from this computer”.", "“get my shaman up to level 80”.", "“get ice cream”."]'::jsonb,'D',null from public.exams where slug='unesp-2024-fase1' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,30,'Conhecimentos Gerais','The benefits of computer games in education are clear. They engage students, improve problem-solving skills, enhance creativity and imagination, allow for personalized learning, remote learning, learning on demand, and contacting peers around the world. With the increasing use of technology in schools, it is essential that teachers explore the potential benefits of computer games and incorporate them into their teaching methods. Doing so can create a more engaging and effective learning environment for their students. (Ruby Butz. https://gamingrespawn.com, 23.03.2023. Adaptado.) According to the text, one of the advantages of computer games in education is:',null,'{"original": ["/unesp-2024/q30-1.png"], "support": []}','["behaviour management tools for teachers.", "enhancement of problem-solving skills.", "doubtful teaching methods.", "friendly learning environment.", "face-to-face contact among peers."]'::jsonb,'B',null from public.exams where slug='unesp-2024-fase1' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,31,'Conhecimentos Gerais','Observe as fachadas de duas igrejas. À esquerda, a Basílica de San Michele, construída no século XII em Pavia, na Itália. À direita, a Catedral de Reims, erguida a partir do século XIII em Reims, na França. (Georges Duby e Michel Laclotte (orgs.). História artística da Europa: a Idade Média II, 1998.) As duas fachadas',null,'{"original": ["/unesp-2024/q31-1.png"], "support": []}','["diferenciam-se pela pouca ornamentação de San Michele, que expressa o estilo românico, e pela monumentalidade e sofisticação de Reims.", "diferenciam-se pela solidez de San Michele, que simbo- liza a força espiritual do catolicismo, e pela carência de detalhes na sede papal em Reims.", "igualam-se na suntuosidade e no rebuscamento arquite- tônico, indicando o poderio econômico da Igreja católica.", "diferenciam-se pela discrição de San Michele, que revela o rigor na conduta dos protestantes, e pela ostentação da riqueza católica de Reims.", "igualam-se na caracterização gótica, revelando a busca da verticalidade como símbolo do poder divino."]'::jsonb,'A',null from public.exams where slug='unesp-2024-fase1' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,32,'Conhecimentos Gerais','Examine o meme, publicado pelo perfil “[b]rasilien” no Tumblr. (https://b-rasil.tumblr.com. Adaptado.) O meme corresponde a uma espécie de metáfora da história do Brasil e, mais precisamente, da',null,'{"original": ["/unesp-2024/q32-1.png"], "support": []}','["dinâmica da colonização do Brasil por Portugal, baseada na exploração e no exclusivo metropolitano do comércio colonial.", "subserviência portuguesa ante os interesses britânicos, que impediam um relacionamento comercial harmonioso entre colônia e metrópole.", "persistência do domínio político português sobre o Brasil, que prosseguiu mesmo depois da independência.", "relação de cumplicidade entre portugueses e brasileiros, construída a partir dos séculos de convivência entre os dois povos.", "corrida do ouro nas Minas Gerais, que atraiu para a região milhares de exploradores da metrópole e das demais áreas da colônia."]'::jsonb,'A',null from public.exams where slug='unesp-2024-fase1' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,33,'Conhecimentos Gerais','O mundo natural é o concreto, que tocamos, sentimos, no qual vivemos. O mundo social é resultado da nossa vida em grupo e em determinado meio ambiente. O mundo sobrenatural é o das religiões, da magia, ao qual os homens só têm acesso parcial, por meio de determinados ritos e cerimônias. Ele é mais ou menos importante, dependendo da sociedade. Numa sociedade como a nossa, na qual quase tudo é explicado pela ciência e pelo pensamento lógico e racional, o espaço do sobrenatural é bastante limitado. Já nas sociedades africanas, onde foram capturados os escravizados trazidos para o Brasil, toda a vida na terra estava ligada ao além, a dimensões que só conhecedores dos ritos e objetos sacralizados podiam atingir. (Marina de Mello e Souza. África e Brasil africano, 2007. Adaptado.) Ao comparar o pensamento lógico predominante no Ocidente contemporâneo com as mentalidades das sociedades africanas de onde foi proveniente a maioria das pessoas trazidas ao Brasil como escravizadas, o excerto',null,'{"original": ["/unesp-2024/q33-1.png"], "support": []}','["critica a relativização dos valores morais e religiosos nas sociedades africanas e europeias no período do tráfico de escravizados.", "identifica o descompasso entre o primitivismo dos povos africanos e o avanço civilizatório da Europa colonizadora.", "caracteriza duas percepções de mundo, enfatizando sua diferença na relação com as dimensões míticas e sagradas.", "distingue dois modelos de pensamento, sustentando a superioridade daquele que é movido pelo esforço racional.", "valoriza a religiosidade do mundo atual, destacando a centralidade das crenças e das práticas religiosas cotidianas."]'::jsonb,'C',null from public.exams where slug='unesp-2024-fase1' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,34,'Conhecimentos Gerais','O espaço urbano é onde proliferavam a pobreza e certa autonomia dos desqualificados sociais, bastante incômoda para as autoridades. Era justamente este o espaço social das mulheres pobres, livres, forras e escravizadas. Circulavam pelas fontes públicas, tanques, lavadouros, pontes, ruas e praças da cidade, onde era jogado o lixo das casas e o mato crescia a ponto de ocultar escravizados fugidos: o seu espaço social era justamente o ponto de interseção onde se alternavam e se sobrepunham as áreas de convívio das vizinhanças e dos forasteiros; a do fisco municipal e a do pequeno comércio clandestino; as margens da escravidão e do trabalho livre, o espaço do trabalho doméstico e o de sua extensão ou comercialização pelas ruas… (Maria Odila Leite da Silva Dias. “Mulheres sem história”. In: Revista de História, 1983. Adaptado.) Ao tratar de São Paulo do século XVIII, o excerto estabelece um paralelo entre a condição das mulheres no espaço urbano e',null,'{"original": ["/unesp-2024/q34-1.png"], "support": []}','["a situação de abandono das crianças pobres da colônia.", "a constituição de um padrão ideal de família burguesa.", "o prevalecimento dos interesses políticos da metrópole.", "a área de indefinição social, política ou econômica.", "os setores da sociedade defensores de propostas identitárias."]'::jsonb,'D',null from public.exams where slug='unesp-2024-fase1' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,35,'Conhecimentos Gerais','O que o Carnaval [na Idade Moderna] significava para o povo que participava dele? Num sentido, a pergunta é desnecessária. O Carnaval era um feriado, uma brincadeira, um fim em si mesmo, dispensando qualquer explicação ou justificativa. Era uma ocasião de êxtase e liberação. [...] Por que o povo usava máscaras com narigões, por que atiravam ovos? [...] Havia três temas principais no Carnaval, reais e simbólicos: comida, sexo e violência. (Peter Burke. Cultura popular na Idade Moderna, 1989.) “O Carnaval sempre foi um ato político, ele está longe de ser uma festa da alienação [...]”, diz o historiador e professor Luiz Antonio Simas. [...] “O Carnaval quebra um padrão de normatividade que é regra durante todo o ano. É nesse momento que os grupos mais vulneráveis se sentem mais livres para exercer toda a sua diversidade”, diz Simas. (Isabela Palhares. “Carnaval pós-restrições da pandemia é apoteose da folia, dizem historiadores”. www.folha.uol.com.br, 20.02.2023.) Os excertos abordam o significado do Carnaval em dois períodos históricos bastante distintos e',null,'{"original": ["/unesp-2024/q35-1.png"], "support": []}','["coincidem, ao indicar contradições da festa: a alegria da manifestação dos prazeres individuais e a tristeza diante da extrema violência do evento.", "coincidem, ao identificar duas dimensões da festa: uma mais imediata, a do prazer, e outra mais profunda, a de transformação comportamental.", "divergem, ao caracterizar a festa na Idade Moderna como ação política e a festa nos dias de hoje como puro divertimento e lazer.", "coincidem, ao mencionar os problemas da festa: um de ordem pública, a explicitação do sexo, e um de ordem privada, a carência alimentar.", "divergem, ao expor a autenticidade e espontaneidade da festa na Idade Moderna e o artificialismo e convenciona- lismo da festa nos dias de hoje."]'::jsonb,'B',null from public.exams where slug='unesp-2024-fase1' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,36,'Conhecimentos Gerais','Não reconhecendo nós outra soberania mais de que a soberania do povo, para ela apelamos. […] Neste país, que se presume constitucional, e onde só deveriam ter ação poderes delegados, […] só há um poder ativo, […] poder sagrado inviolável e irresponsável. O privilégio, em todas as suas relações com a sociedade — tal é, em síntese, a fórmula social e política do nosso país —, privilégio de religião, privilégio de raça, privilégio de sabedoria, privilégio de posição, isto é, todas as distinções arbitrárias e odiosas que criam no seio da sociedade civil e política a monstruosa superioridade de um sobre todos ou de alguns sobre muitos. […] A autonomia das províncias é, pois, para nós mais do que um interesse imposto pela solidariedade dos direitos e das relações provinciais, é um princípio cardeal e solene que inscrevemos na nossa bandeira. (“Manifesto Republicano de 1870”. In: Américo Brasiliense. Os programas dos partidos e o 2o Império, 1878.) O trecho transcrito permite caracterizar o Manifesto Republicano como',null,'{"original": ["/unesp-2024/q36-1.png"], "support": []}','["racista e liberal.", "federalista e socialista.", "socialista e unitarista.", "unitarista e racista.", "democrata e federalista."]'::jsonb,'E',null from public.exams where slug='unesp-2024-fase1' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,37,'Conhecimentos Gerais','Observe as imagens. A da esquerda é intitulada “Plantas do Orquidário Moderno” (1845). A da direita intitula-se “Madame Professora” (1846). (In: Peter Gay. A experiência burguesa da Rainha Vitória a Freud: a educação dos sentidos, 1988.) As duas imagens referem-se a algumas sociedades europeias do século XIX e',null,'{"original": ["/unesp-2024/q37-1.png"], "support": []}','["representam, com ironia, os novos papéis exercidos pelas mulheres nas sociedades do período.", "aludem, com humor, ao avanço das pesquisas e do ensi- no nas sociedades do período.", "constatam a substituição da estrutura patriarcal pelo matriarcalismo nas sociedades industriais.", "ilustram, com surpresa, a padronização do trabalho femi- nino nas sociedades de economia industrial.", "celebram a liderança política feminina numa sociedade de hegemonia liberal."]'::jsonb,'A',null from public.exams where slug='unesp-2024-fase1' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,38,'Conhecimentos Gerais','A América independente, a América Latina, traz no íntimo a América pré-colombiana, que desponta por todos os seus poros, resistindo ao novo cerco, agora em forma de Estados nacionais que se estabeleceram violentando as linhas históricas de demarcação das diferentes culturas. Em muitos casos, os povos foram fragmentados pelas fronteiras nacionais, e seus fluxos, interrompidos ou entorpecidos. (Ana Esther Ceceña. “Uma versão mesoamericana da América Latina”. In: Adauto Novaes (org.). Oito visões da América Latina, 2006.) Com base no trecho, conclui-se que “a América independente, a América Latina, traz no íntimo a América pré- -colombiana”,',null,'{"original": ["/unesp-2024/q38-1.png"], "support": []}','["pois as lutas pela emancipação política do continente incorporaram valores e princípios culturais dos povos nativos americanos.", "pois os caminhos da história latino-americana permitiram a integração e a miscigenação dos povos originários do continente com europeus e africanos.", "apesar de os processos históricos posteriores à Con- quista europeia e à formação nacional terem imposto outra configuração territorial ao continente.", "apesar de o avanço dos interesses econômicos britâni- cos no continente ter provocado um maior interesse pe- las tradições culturais anglo-saxônicas.", "apesar de os povos originários do continente terem sido dizimados no momento da Conquista europeia e substi- tuídos por africanos escravizados."]'::jsonb,'C',null from public.exams where slug='unesp-2024-fase1' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,39,'Conhecimentos Gerais','Analise a imagem, que mostra a queima de café em Santos, SP, em 1931. (https://epoca.oglobo.globo.com) A cena, ocorrida durante o governo provisório de Getúlio Vargas, resulta',null,'{"original": ["/unesp-2024/q39-1.png"], "support": []}','["da ausência de um plano de apoio governamental ao agronegócio, motor das exportações brasileiras.", "da disposição de Vargas de destruir estoques de café para reduzir a força política e econômica dos cafeiculto- res paulistas.", "dos limites do projeto varguista de erradicar a fome no país por meio da proibição da exportação de alimentos.", "do projeto de industrialização implementado por Vargas, que retirava a subvenção ao setor agrário.", "dos impasses de uma economia de base agroexporta- dora, afetada pela contração do mercado consumidor internacional."]'::jsonb,'E',null from public.exams where slug='unesp-2024-fase1' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,40,'Conhecimentos Gerais','Era a Índia que nos sustentava nas dificuldades de nossas circunstâncias. Era um aspecto de nossa identidade, da identidade comum que tínhamos desenvolvido e que, na Trinidad multirracial, se tornara uma identidade racial. Era essa a identidade que eu levara para a Índia em minha primeira visita em 1962. Ao chegar, percebi que isso nada significava na Índia. A ideia de uma comunidade indiana — na verdade uma ideia europeia de nossa identidade indiana — apenas tinha sentido quando a comunidade era muito pequena, minoritária e isolada. Na torrente da Índia, com suas centenas de milhões, onde a ameaça eram o caos e o vazio, essa noção europeia em nada ajudava. (V.S. Naipaul. Índia: um milhão de motins agora, 1997.) O excerto traz o relato de um escritor de ascendência indiana, nascido em Trinidad e Tobago, quando de sua primeira viagem para a Índia. Segundo ele, há',null,'{"original": ["/unesp-2024/q40-1.png"], "support": []}','["um impasse sociopolítico na Índia atual, pois o país teve um passado glorioso, mas não conseguiu se reorganizar política e economicamente após o fim do domínio colo- nial britânico sobre a região.", "uma continuidade entre a Índia do período de coloniza- ção europeia e a Índia independente, pois os indianos que vivem dentro e fora do país sentem-se pertencentes ao mesmo grupo nacional-identitário.", "uma identidade comum de origem religiosa, que se mani- festa de maneira igual no conjunto de indianos que vivem na Índia e nas comunidades de descendentes de india- nos organizadas em outros países.", "um descompasso entre a percepção da Índia que se tem de fora do país asiático, e que é afetada por valores na- cionais de origem europeia, e a percepção que os pró- prios indianos têm de seus vínculos sociais.", "uma ruptura entre o passado histórico indiano, que se as- socia ao domínio político-militar que o país exerceu sobre o subcontinente asiático, e o presente de superpopula- ção provocada pela colonização europeia."]'::jsonb,'D',null from public.exams where slug='unesp-2024-fase1' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,41,'Conhecimentos Gerais','O verdadeiro horror dos campos de concentração e de extermínio reside no fato de os internados, mesmo que consigam manter-se vivos, estarem mais isolados do mundo dos vivos do que se tivessem morrido, porque o horror compele ao esquecimento. No mundo concentracionário, mata-se um homem tão impessoalmente como se mata um mosquito. Uma pessoa pode morrer em consequência de tortura ou de fome sistemática, ou porque o campo está superpovoado e há necessidade de liquidar o material humano supérfluo. (Hannah Arendt. O sistema totalitário, 1978.) Ao caracterizar a peculiaridade das ações nazistas nos campos de concentração e de extermínio, o excerto refere-se diretamente',null,'{"original": ["/unesp-2024/q41-1.png"], "support": []}','["à ausência de condições básicas de higiene.", "à coisificação dos prisioneiros.", "ao respeito aos direitos humanos.", "ao prevalecimento do nacionalismo.", "à escravização dos prisioneiros."]'::jsonb,'B',null from public.exams where slug='unesp-2024-fase1' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,42,'Conhecimentos Gerais','Examine a tabela de investimentos em infraestrutura econômica no Brasil, no período de 1990 a 1998, com os volumes de capitais expressos em bilhões de dólares e suas respectivas proporções em relação ao Produto Interno Bruto (PIB). Tele- Setores Energia Transportes Total comunicações US$ bi % PIB US$ bi % PIB US$ bi % PIB US$ bi % PIB 1990 8,8 2,40 1,6 0,44 0,6 0,16 11,0 3,0 1991 5,7 1,52 2,8 0,74 0,9 0,24 9,4 2,5 1992 4,9 1,18 2,8 0,68 1,0 0,24 8,7 2,1 1993 4,5 0,99 3,2 0,71 0,9 0,20 8,6 1,9 1994 3,9 0,66 3,2 0,54 1,2 0,20 8,3 1,4 1995 4,2 0,68 4,0 0,65 1,1 0,18 9,3 1,5 1996 4,0 0,59 6,0 0,88 1,6 0,23 11,6 1,7 1997 4,8 0,56 7,5 0,87 1,5 0,17 13,8 1,6 1998 5,4 0,60 3,7 0,41 0,8 0,09 9,9 1,1 (Ricardo Carneiro. Desenvolvimento em crise: a economia brasileira no último quarto do século XX, 2002. Adaptado.) A partir dos dados da tabela e considerando a experiência histórica brasileira no período, tem-se que',null,'{"original": ["/unesp-2024/q42-1.png"], "support": []}','["o investimento no setor de transportes teve aumento con- tínuo após 1994, em virtude da aceleração do crescimen- to econômico provocado pelo Plano Real.", "o setor de telecomunicações, impulsionado pelas mudan- ças tecnológicas em curso, recebeu, em 1996 e 1997, mais da metade dos investimentos realizados nos três setores nestes dois anos.", "o percentual do PIB foi reduzido, em 1998, à metade do que era no primeiro ano do período analisado, indicando a retração econômica provocada pelos planos de estabi- lização da inflação.", "o setor energético recebeu maiores investimentos no pe- ríodo posterior ao Plano Real, devido à exploração de petróleo nas áreas do Pré-Sal, realizada ao longo de todo o período analisado.", "o setor de transportes recebeu suas maiores porcenta- gens de investimentos em 1995 e em 1997, em razão do forte aumento do percentual do PIB ocorrido nestes dois anos."]'::jsonb,'B',null from public.exams where slug='unesp-2024-fase1' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,43,'Conhecimentos Gerais','Países-membros europeus da Otan em abril de 2023 A expansão da Otan (Organização do Tratado do Atlântico Norte) na direção do Leste Europeu é um dos motivos alegados por Vladimir Putin para invadir a Ucrânia. A Finlândia não é uma ex-república soviética, tampouco fazia parte dos países da cortina de ferro. Mas desde que encerrou a Guerra de Inverno com a União Soviética, ocorrida entre 1939 e 1940, em meio à Segunda Guerra Mundial, mantinha-se neutra na queda de braço entre Otan e Rússia, que reivindica a influência geopolítica antes exercida pelo extinto bloco comunista. Essa neutralidade foi encerrada em 2022, quando a Finlândia abriu o processo para entrar na aliança. A conclusão desse processo resultou na adesão da Finlândia como país-membro da Otan a partir de 04 de abril de 2023. (www.nexojornal.com.br, 04.04.2023. Adaptado.) A entrada da Finlândia na Otan fundamenta-se',null,'{"original": ["/unesp-2024/q43-1.png"], "support": []}','["no acordo militar de defesa mútua entre os países- -membros.", "na proteção do comércio entre os países-membros.", "no fortalecimento da união monetária entre os países- -membros.", "na concessão de investimentos entre os países-membros.", "no compromisso de uma união política entre os países- -membros."]'::jsonb,'A',null from public.exams where slug='unesp-2024-fase1' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,44,'Conhecimentos Gerais','Leia as manchetes. Com o premiado filme “Parasita”, Coreia do Sul espalha seu “soft power” pelo mundo (https://tab.uol.com.br, 07.11.2019. Adaptado.) Da banda de música pop “BTS” ao filme “Parasita”, entenda como a Coreia do Sul aplica o “soft power” (www.poder360.com.br, 05.04.2022. Adaptado.) Da série “Round 6” ao estilo musical “K-pop”, cultura sul- -coreana é novo vetor do “soft power” de Seul (www.rfi.fr/br, 14.10.2021. Adaptado.) O “soft power” citado nas manchetes corresponde',null,'{"original": ["/unesp-2024/q44-1.png"], "support": []}','["à alienação de consumidores quanto à origem de seus produtos, ou seja, ao desconhecimento sobre a atual divisão internacional do trabalho.", "ao domínio do mercado pelo uso da coerção, ou seja, à construção de uma relação de dependência dos merca- dos em relação ao mundo oriental.", "à busca de uma hegemonia por consenso, ou seja, à uti- lização da indústria cultural para se fazer presente em diversos países.", "à estratégia de combate à xenofobia nos países ociden- tais, ou seja, ao fortalecimento da democratização do consumo de produtos culturais em escala supranacional.", "ao redesenho da hierarquia político-econômica, ou seja, ao retorno à velha ordem mundial pautada pelo consumo cultural."]'::jsonb,'C',null from public.exams where slug='unesp-2024-fase1' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,45,'Conhecimentos Gerais','O just in time é responsável por buscar a precisão da cadeia de produção, encaixando as operações e as execuções de acordo com o nível de demanda. Ou seja, tudo ocorre no seu devido tempo, nem antes nem depois. Essa metodologia evita o estoque parado e o desperdício de matéria-prima. (www.totvs.com, 11.07.2022.) A metodologia apresentada no excerto é aplicada pelo',null,'{"original": ["/unesp-2024/q45-1.png"], "support": []}','["taylorismo, ideal produtivo estimulado pela União Soviéti- ca durante a Guerra Fria, em um cenário de crescimento homogêneo para as suas repúblicas.", "mercantilismo, doutrina econômica estipulada pela China no final do século XX, em conformidade ao seu desejo de ser um plataforma de exportação.", "desenvolvimentismo, sistema de gestão corporativa cria- do nos Estados Unidos no fim do século XIX, em associa- ção à expansão do capitalismo pelo mundo.", "fordismo, princípio de produção industrial inaugurado pela Inglaterra após a Segunda Guerra Mundial, em que a esteira rolante dita o ritmo produtivo.", "toyotismo, modelo de organização do trabalho desenvol- vido no Japão após a Segunda Guerra Mundial, em um contexto de restrições naturais e econômicas."]'::jsonb,'E',null from public.exams where slug='unesp-2024-fase1' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,46,'Conhecimentos Gerais','Há uma comunidade de fanáticos por geografia que cresce rapidamente em torno de um jogo. A premissa é simples: o jogador que observa a tela de seu computador ou celular é conduzido a algum canto do planeta, por meio de imagens, e tem de adivinhar, o mais rápido possível, que lugar, exatamente, é apresentado. Quanto mais próximo for seu palpite do lugar mostrado na imagem, maior o número de pontos recebido. (www.folha.uol.com.br, 12.07.2022. Adaptado.) (www.youtube.com/@republicacoisadenerd) Sob o ponto de vista geográfico, os jogadores mencionados no excerto operacionalizam conhecimentos relacionados',null,'{"original": ["/unesp-2024/q46-1.png"], "support": []}','["ao cálculo da densidade demográfica.", "aos múltiplos fusos horários.", "à organização político-administrativa.", "às diferenças socioespaciais.", "à observação da unificação técnica."]'::jsonb,'D',null from public.exams where slug='unesp-2024-fase1' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,47,'Conhecimentos Gerais','No Sertão Nordestino, oligarquias representam um dos polos na desigual estrutura social, econômica e política da região. Durante o século XX, a oligarquia nordestina beneficiou-se',null,'{"original": ["/unesp-2024/q47-1.png"], "support": []}','["da transposição do rio São Francisco, obra que obje- tivou desviar parte das águas desse rio para rios in- termitentes com maior capacidade de abastecimento hídrico de áreas rurais e urbanas.", "da indústria da seca, expressão que designa a relação entre a realidade de fome e miséria da população duran- te as longas estiagens e os recursos destinados a obras para melhorias na qualidade de vida local.", "da remarcação de fronteiras estaduais, estratégia empre- gada para melhorar os resultados de investimentos fede- rais realizados na promoção de serviços de tratamento de água e esgoto.", "da implantação do Projeto Grande Carajás, empreendi- mento privado que objetivou dinamizar a economia nor- destina com maciços investimentos em infraestruturas produtivas agrícolas.", "da transferência da capital federal para Brasília, decisão que atrelou o uso de mão de obra e de empresas nordes- tinas para reaquecer o setor de produção de matérias- -primas da região Nordeste."]'::jsonb,'B',null from public.exams where slug='unesp-2024-fase1' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,48,'Conhecimentos Gerais','Analise a charge do cartunista Seri. (www.dgabc.com.br, 13.10.2022.) Ao se referir ao Censo, a charge',null,'{"original": ["/unesp-2024/q48-1.png"], "support": []}','["denuncia o preconceito socioeconômico do Censo e traz ao debate a angústia da população carente, à margem das conquistas que possam oferecer justiça social.", "satiriza a falta de empatia dos recenseadores e demons- tra a insatisfação da população com os serviços públicos, precários àqueles que dependem de sua oferta.", "associa o atraso ao grau de desenvolvimento da popu- lação e transfere às pessoas a responsabilidade por sua condição, distante da noção de equidade.", "minimiza a importância do Censo e critica o imediatismo observado em nossa sociedade, marcada pela desvalori- zação da reflexão e do senso crítico.", "ironiza o atraso na realização do Censo e remete a uma de suas funções, a de embasar políticas públicas com dados sobre a realidade da população."]'::jsonb,'E',null from public.exams where slug='unesp-2024-fase1' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,49,'Conhecimentos Gerais','Analise o mapa que apresenta as placas tectônicas envolvidas no terremoto ocorrido na região de Anatólia, na Turquia, em fevereiro de 2023. (www.ipma.pt. Adaptado.) Segundo a classificação das placas tectônicas quanto ao tipo de deslocamento, o terremoto na região de Anatólia está relacionado',null,'{"original": ["/unesp-2024/q49-1.png"], "support": []}','["ao movimento de uma placa sobre a outra, ao longo de uma fossa.", "ao afundamento de uma placa em relação à outra, ao longo de uma montanha.", "ao movimento de uma placa em relação à outra, ao longo de uma falha.", "ao afundamento de uma placa sob a outra, ao longo de um continente.", "ao distanciamento de uma placa em relação à outra, ao longo de uma dorsal."]'::jsonb,'C',null from public.exams where slug='unesp-2024-fase1' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,50,'Conhecimentos Gerais','Analise o gráfico. (http://educacao.globo.com. Adaptado.) As variações na temperatura e na umidade estão relacionadas ao tipo e à intensidade do intemperismo, determinantes para a formação dos solos. A partir do gráfico e com fundamento na ciência dos solos, tem-se que,',null,'{"original": ["/unesp-2024/q50-1.png"], "support": []}','["em climas áridos, os solos possuem pedaços da rocha matriz.", "em climas úmidos, os solos possuem camada menor de argila.", "em climas frios, os solos são ricos em matéria orgânica.", "em climas tropicais, os solos são pouco permeáveis à água.", "em climas secos, os solos possuem baixa porcentagem de minerais."]'::jsonb,'A',null from public.exams where slug='unesp-2024-fase1' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,51,'Conhecimentos Gerais','Examine a imagem, que apresenta a classificação dos rios segundo o grau de ramificações dentro de uma bacia hidrográfica. (Fillipe T. P. Torres. Introdução à hidrogeografia, 2012. Adaptado.) O exame da classificação dos rios revela que',null,'{"original": ["/unesp-2024/q51-1.png"], "support": []}','["os rios de segunda ordem estão próximos aos afluentes, áreas de terrenos mais planos e com muitas rochas.", "os rios de primeira ordem estão próximos às nascentes, áreas mais elevadas e de maior declividade.", "os rios de terceira ordem estão próximos aos leitos, áreas independentes dos regimes de cheias e vazantes.", "os rios de quarta ordem estão próximos à foz, área com um regime turbulento e mais veloz.", "os rios de quarta ordem estão próximos aos divisores de água, áreas com grande capacidade erosiva e mais sedimentos."]'::jsonb,'B',null from public.exams where slug='unesp-2024-fase1' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,52,'Conhecimentos Gerais','Nos últimos séculos, há um descompasso entre os problemas ambientais e a consciência ambiental sobre a gravidade desses problemas. O fato histórico que marca a maior intensidade dos impactos no meio ambiente',null,'{"original": ["/unesp-2024/q52-1.png"], "support": []}','["são as Grandes Navegações, encerradas no século XV.", "é a Primeira Guerra Mundial, ocorrida em meados do século XIX.", "é a Metropolização, instituída no século XXI.", "é a Revolução Industrial, iniciada no século XVIII.", "são as Revoluções Técnico-Científico-Informacionais, fundadas no século XIX."]'::jsonb,'D',null from public.exams where slug='unesp-2024-fase1' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,53,'Conhecimentos Gerais','O comércio de peixes ornamentais é um mercado que movimenta milhares de dólares no Brasil e no mundo, porém, essa atividade também é uma das principais fontes de introdução de espécies exóticas. Só no Brasil, mais de 70 espécies de peixes ornamentais não nativos já foram identificadas no ambiente natural, incluindo recentemente o peixe conhecido como paulistinha ou peixe-zebra, nativo do sul da Ásia. (https://conexaoplaneta.com.br. Adaptado.) Os peixes ornamentais exóticos tratados no excerto, quando encontrados em rios brasileiros, caracterizam a chamada',null,'{"original": ["/unesp-2024/q53-1.png"], "support": []}','["biotecnologia, em que o emprego de recursos técnicos se torna uma opção para corrigir as assimetrias dos proces- sos naturais, como o mutualismo e a competição.", "ressurgência, em que a oferta de condições naturais ideais para determinada espécie possibilita seu cresci- mento em números relativos.", "invasão biológica, em que uma espécie, fora de seu ambiente natural, pode crescer de maneira descontro- lada e provocar desequilíbrio no ecossistema.", "explosão demográfica, em que uma espécie, por adapta- ção, reduz a taxa de mortalidade e passa a registrar um grande crescimento natural.", "biopirataria, em que espécies animais ou conheci- mentos tradicionais são explorados, de forma legal, por pesquisadores."]'::jsonb,'C',null from public.exams where slug='unesp-2024-fase1' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,54,'Conhecimentos Gerais','Na escola, Maria recebeu de seu professor de Geografia a tarefa de construir um globo terrestre — uma representação cartográfica em superfície esférica. Se a estudante utilizar uma bola de isopor com 12 cm de raio e considerar que a circunferência da Terra tenha 40 000 km, a escala numérica aproximada do globo terrestre será:',null,'{"original": ["/unesp-2024/q54-1.png"], "support": []}','["1: 6 369.", "1: 480 000.", "1: 530.", "1: 3 333.", "1: 53 075 000."]'::jsonb,'E',null from public.exams where slug='unesp-2024-fase1' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,55,'Conhecimentos Gerais','Não existe definição objetiva, nem muito menos neutra, daquilo que é ou não a ciência. Esta tanto pode ser uma procura metódica do saber quanto um modo de interpretar a realidade; tanto pode ser uma instituição, com seus grupos de pressão, seus preconceitos, suas recompensas oficiais, quanto uma atuação subordinada a instâncias administrativas, políticas ou ideológicas. Se perguntarmos sobre o modo de funcionamento da ciência, sobre seu papel social, sobre sua maneira de explicar os fenômenos e de compreender o ser humano no mundo, perceberemos facilmente que as condições reais em que são produzidos os conhecimentos objetivos e racionalizados estão banhadas por uma inegável atmosfera sócio-político-cultural. (Hilton Japiassu. O mito da neutralidade científica, 1975. Adaptado.) A consideração de Hilton Japiassu em relação à neutralidade da ciência destaca',null,'{"original": ["/unesp-2024/q55-1.png"], "support": []}','["a inexistência de método seguro.", "o enviesamento do fazer científico.", "a falta de recursos materiais nas pesquisas.", "a submissão do saber ao senso comum.", "o rompimento com o dogmatismo religioso."]'::jsonb,'B',null from public.exams where slug='unesp-2024-fase1' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,56,'Conhecimentos Gerais','Texto 1 (Gerson Pastre de Oliveira (org.). Pesquisa em educação e educação matemática: um olhar sobre a metodologia, 2019. Adaptado.) Texto 2 O conhecimento teórico da natureza — originariamente ligado à geometria — como visão ideal da perfeição harmoniosa do cosmo foi se desenvolvendo paralelamente à evolução da matemática, deixando, assim, de forma paulatina, de ser simples forma de contemplação da realidade, para adquirir o caráter de um instrumento de conhecimento da natureza. (Milton Vargas. “História da matematização da natureza”. Estudos Avançados, 1996.) A relação entre Filosofia e Matemática advém de um longo período da história da humanidade. Pode-se observar tal relação, a partir dos textos 1 e 2, pela',null,'{"original": ["/unesp-2024/q56-1.png"], "support": []}','["utilização da ideia de primeiro motor na formulação do conhecimento medieval.", "influência do dualismo platônico na teoria cartesiana.", "presença da causalidade aristotélica em explicações da física newtoniana.", "repercussão da ideia de arché como número na ciência moderna.", "ruptura com o entendimento de cosmos geocêntrico em Copérnico."]'::jsonb,'D',null from public.exams where slug='unesp-2024-fase1' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,57,'Conhecimentos Gerais','Analise a reprodução da obra Latas de Sopa Campbell, de Andy Warhol, produzida em 1962, e leia o excerto do livro Arte Pop, de David McCarthy. Texto 1 (https://origins.osu.edu) Texto 2 As declarações de artistas pop sugerem que eles estavam não só familiarizados, mas à vontade no mundo da produção e do consumo do pós-guerra. Embora o tema de sua arte reconhecesse diretamente a rápida disseminação de bens comerciais disponíveis em quantidades crescentes ao longo da década de 1950, o estilo dessa arte adotava o desenho chamativo da propaganda. O status da arte pop como produto é inseparável de seu apelo por consumo. (Arte Pop, 2002. Adaptado.) No período pós-Segunda Guerra, a estreita relação entre o movimento Pop Art e a estética da propaganda deve-se à',null,'{"original": ["/unesp-2024/q57-1.png"], "support": []}','["alta dos valores das obras junto aos colecionadores.", "influência dos patrocinadores entre os artistas estaduni- denses.", "recusa das técnicas artesanais na produção artística.", "ruptura artística com os parâmetros econômicos desse período.", "transformação da arte provocada pela lógica capitalista."]'::jsonb,'E',null from public.exams where slug='unesp-2024-fase1' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,58,'Conhecimentos Gerais','A emergência do ChatGPT, chatbot (software capaz de simular a conversação humana) desenvolvido pela OpenAI, chamou a atenção internacional. Essa nova ferramenta de inteligência artificial pode revolucionar um leque extremamente amplo de atividades humanas, mas não deixou de despertar também um considerável número de preocupações entre especialistas de tecnologia. O ChatGPT é capaz de entender a linguagem humana natural e gerar uma resposta semelhante ao fruto do intelecto humano após receber um pedido. A ferramenta ganhou destaque pelo nível extremamente refinado de suas respostas. (Luca Belli e Nina da Hora. “ChatGPT: o que anima e o que assusta na nova inteligência artificial”. Folha de S.Paulo, 20.01.2023. Adaptado.) Diante do cenário descrito no excerto, a utilização da nova tecnologia de maneira eticamente responsável requer a',null,'{"original": ["/unesp-2024/q58-1.png"], "support": []}','["livre concorrência para disputa comercial entre empresas privadas.", "massificação de dispositivos de tecnologias de lingua- gem natural.", "promoção de campanhas sobre os prejuízos do uso desse tipo de software.", "permissão de acesso a assinantes dessa ferramenta devidamente identificados.", "censura estatal do avanço de programas de inteligência artificial."]'::jsonb,'C',null from public.exams where slug='unesp-2024-fase1' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,59,'Conhecimentos Gerais','A uberização nomeia um novo tipo de gestão e controle da força de trabalho, também compreendida como uma tendência passível de se generalizar no âmbito das relações de trabalho. […] Resultando das formas contemporâneas de eliminação de direitos, transferência de riscos e custos para os trabalhadores e novos arranjos produtivos, ela em alguma medida sintetiza processos em curso há décadas, ao mesmo tempo em que se apresenta como tendência para o futuro do trabalho. O tema ganha visibilidade com a formação de enormes contingentes de trabalhadores controlados por empresas que operam por meio de plataformas digitais. (Ludmila Costhek Abílio et al. “Uberização e plataformização do trabalho no Brasil: conceitos, processos e formas”. Sociologias, 2021.) O excerto aborda as novas relações trabalhistas mediadas por plataformas digitais. Com tais relações, nos próximos anos o futuro do trabalho será definido pela',null,'{"original": ["/unesp-2024/q59-1.png"], "support": []}','["autogestão do trabalhador na relação com grandes empresas.", "queda na geração de vagas no setor informal.", "persistência de mecanismos de exploração.", "extinção de postos de serviço no setor primário.", "flexibilidade na jornada de trabalho do profissional não autônomo."]'::jsonb,'C',null from public.exams where slug='unesp-2024-fase1' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,60,'Conhecimentos Gerais','Um imperativo adequado ao novo tipo de agir humano e voltado para o novo tipo de sujeito atuante deveria ser mais ou menos assim: “Aja de modo a que os efeitos da sua ação sejam compatíveis com a permanência de uma autêntica vida humana sobre a Terra”; ou, expresso negativamente: “Aja de modo a que os efeitos da sua ação não sejam destrutivos para a possibilidade futura de uma tal vida; ou, simplesmente: “Não ponha em perigo as condições necessárias para a conservação indefinida da humanidade sobre a Terra”. O atual imperativo humano se estende em direção a um previsível futuro concreto, que constitui a dimensão inacabada de nossa responsabilidade. (Hans Jonas. O princípio responsabilidade, 2006. Adaptado.) Considerando o excerto e as atuais questões ambientais, Hans Jonas defende',null,'{"original": ["/unesp-2024/q60-1.png"], "support": []}','["o estabelecimento de uma ética normativa.", "o planejamento de uma nova conferência mundial sobre o tema.", "a fundamentação das decisões individuais isoladas.", "a manutenção dos impactos humanos na natureza.", "a constituição de um órgão intergovernamental."]'::jsonb,'A',null from public.exams where slug='unesp-2024-fase1' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,61,'Conhecimentos Gerais','O mês de maio é dedicado à conscientização e combate à doença celíaca, uma condição autoimune que afeta cerca de 1% da população mundial. Mas, apesar de sua prevalência, a doença celíaca ainda é pouco conhecida e pouco diagnosticada dentre muitos casos, o que pode levar a complicações de saúde. A doença celíaca ocorre quando o sistema imunológico reage de forma anormal ao glúten, uma proteína presente em muitos alimentos. Isso pode causar inflamação e danos no revestimento do intestino delgado, prejudicando a absorção de nutrientes. Os sintomas podem incluir dor abdominal, diarreia, inchaço e perda de peso. (https://fbg.org.br, maio de 2023. Adaptado.) O tratamento efetivo contra a doença celíaca exige a interrupção do consumo de alimentos que contenham',null,'{"original": ["/unesp-2024/q61-1.png"], "support": ["/unesp-2024/tabela-periodica.png"]}','["frutas cítricas.", "farinha de trigo.", "leite de vaca.", "carne bovina.", "ovos."]'::jsonb,'B',null from public.exams where slug='unesp-2024-fase1' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,62,'Conhecimentos Gerais','O clima quente do país [Brasil] exige a utilização, em grandes quantidades, de defensivos agrícolas, a fim de proteger as lavouras de pragas e de ervas daninhas. Esses defensivos podem gerar impactos significativos sobre a flora e a fauna. Desde meados dos anos 2000, toda uma linha de pesquisa na Unesp tem procurado investigar o impacto desses defensivos sobre as populações de abelhas, animais que desempenham um trabalho ambiental fundamental para a manutenção tanto das matas quanto das próprias lavouras. (https://jornal.unesp.br, 20.05.2022. Adaptado.) O trabalho ambiental fundamental realizado pelas abelhas, citado no excerto,',null,'{"original": ["/unesp-2024/q62-1.png"], "support": ["/unesp-2024/tabela-periodica.png"]}','["aumenta a chance de ocorrer fecundação cruzada em certos vegetais.", "elimina as pragas agrícolas resistentes aos inseticidas.", "reduz a necessidade do uso frequente de defensivos agrícolas.", "impede a autofecundação em plantas que produzem flores.", "aumenta a quantidade de insetos resistentes aos inseti- cidas."]'::jsonb,'A',null from public.exams where slug='unesp-2024-fase1' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,63,'Conhecimentos Gerais','O fenômeno da bioluminescência ocorre em organismos que emitem luz por meio da reação química de oxidação da luciferina catalisada pela enzima luciferase. Em vaga- -lumes, a emissão de luz pela extremidade do abdome atrai parceiros para a reprodução, mas também chama a atenção de predadores. De acordo com a teoria sintética da evolução, a bioluminescência em vaga-lumes pode ser explicada',null,'{"original": ["/unesp-2024/q63-1.png"], "support": ["/unesp-2024/tabela-periodica.png"]}','["pelo estímulo ambiental, que induziu indivíduos adapta- dos a expressarem mais intensamente esse fenômeno.", "pela seleção natural em populações que viviam em am- bientes escuros e emitiam luz através desse fenômeno.", "por mutações e recombinações gênicas em indivíduos que passaram a alterar os alelos responsáveis por esse fenômeno.", "pela necessidade de sobrevivência no escuro, que esti- mulou a produção de moléculas envolvidas nesse fenô- meno.", "pela seleção natural de indivíduos que expressavam os alelos correspondentes às moléculas envolvidas nesse fenômeno."]'::jsonb,'E',null from public.exams where slug='unesp-2024-fase1' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,64,'Conhecimentos Gerais','Leia um trecho da história em quadrinhos “Asterios Polyp”, de David Mazzucchelli. (Asterios Polyp, 2011. Adaptado.) O pensamento resulta da atividade neurológica do cérebro. A enorme maioria dos neurônios que formam o cérebro não é renovada ao longo da vida porque esses neurônios',null,'{"original": ["/unesp-2024/q64-1.png"], "support": ["/unesp-2024/tabela-periodica.png"]}','["são desprovidos de centríolos.", "mantêm todos os genes inibidos.", "são incapazes de formar microtúbulos.", "permanecem na fase G0 da interfase.", "sofrem apoptose celular."]'::jsonb,'D',null from public.exams where slug='unesp-2024-fase1' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,65,'Conhecimentos Gerais','Analise o gráfico que apresenta a porcentagem de células sanguíneas (hematopoiese) que diferentes órgãos humanos produzem ao longo das fases pré-natal e pós-natal. (https://basicmedicalkey.com. Adaptado.) De acordo com o gráfico, as células sanguíneas são produzidas,',null,'{"original": ["/unesp-2024/q65-1.png"], "support": ["/unesp-2024/tabela-periodica.png"]}','["no início da fase pré-natal, por um anexo embrionário que reserva excretas nitrogenadas.", "no final da fase pré-natal, pela medula óssea amarela e pela medula óssea vermelha.", "na fase pré-natal, por um órgão responsável pela produ- ção de sais biliares.", "na fase pós-natal, por órgãos do sistema locomotor liga- dos a músculos lisos.", "na fase pós-natal e a partir dos 30 anos de idade, pelos ossos do sistema esquelético axial."]'::jsonb,'C',null from public.exams where slug='unesp-2024-fase1' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,66,'Conhecimentos Gerais','Pesquisadores avaliaram o perfil epidemiológico dos acidentes ofídicos ocorridos no estado de Minas Gerais entre os anos de 2007 e 2019. Dentre as espécies de serpentes envolvidas, o gênero Bothrops apresentou maiores índices de acidentes ofídicos, seguido por Crotalus, Micrurus e Lachesis. O gráfico apresenta informações sobre o número de registros de acidentes ofídicos por mês, na localidade estudada, considerando-se apenas esses quatro gêneros de serpentes. (“Padrões espaço-temporais dos acidentes ofídicos no estado de Minas Gerais, Brasil”. Journal of Environmental Analysis and Progress, 2022. Adaptado.) A análise do gráfico permite concluir que a frequência de acidentes ofídicos foi',null,'{"original": ["/unesp-2024/q66-1.png"], "support": ["/unesp-2024/tabela-periodica.png"]}','["menor no inverno, período em que as serpentes têm a percepção por meio de seus sensores térmicos reduzida.", "maior no inverno, período em que as serpentes apresen- tam menor desidratação pela superfície corporal.", "menor no inverno, período em que as serpentes dispu- tam alimentos com mais predadores.", "maior no verão, período em que as serpentes permane- cem ativas por mais tempo ao longo dos dias.", "menor no verão, período em que as serpentes se escon- dem em locais sombreados e mais frescos."]'::jsonb,'D',null from public.exams where slug='unesp-2024-fase1' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,67,'Conhecimentos Gerais','Os alelos responsáveis pela determinação genética dos antígenos do sistema sanguíneo ABO estão localizados em um lócus do cromossomo 9. Já o gene para um tipo de daltonismo está localizado em uma região específica do cromossomo sexual X. A imagem a seguir ilustra os dois pares de cromossomos de uma mulher que estão relacionados aos referidos genes. Caso essa mulher se case com um homem do grupo sanguíneo O e não daltônico, a probabilidade de gerarem',null,'{"original": ["/unesp-2024/q67-1.png"], "support": ["/unesp-2024/tabela-periodica.png"]}','["um menino daltônico e do grupo sanguíneo O é 75%.", "uma criança daltônica é 25%.", "uma menina do grupo sanguíneo A é 50%.", "uma criança do grupo sanguíneo O é zero.", "uma menina daltônica e do grupo sanguíneo A é 25%."]'::jsonb,'B',null from public.exams where slug='unesp-2024-fase1' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,68,'Conhecimentos Gerais','A Agência Nacional de Vigilância Sanitária (Anvisa) estabelece que produtos alimentícios que contenham algum nutriente em quantidade elevada e prejudicial à saúde, como açúcar, sódio e gordura, apresentem essa informação em seus rótulos por meio de figuras padronizadas. (www.gov.br) As gorduras são constituídas por misturas de triglicerídeos que, quando hidrolisados no organismo humano, produzem diferentes moléculas de ácidos graxos. O quadro mostra as fórmulas químicas dos ácidos graxos obtidos em maior porcentagem na hidrólise enzimática de dois tipos de gorduras, X e Y. Ácido graxo obtido em maior Tipo de gordura porcentagem na hidrólise enzimática X CH3 – (CH2)8 – COOH Y CH3 – (CH2) – CH = CH – (CH2)5 – COOH A hidrólise enzimática da gordura produz maior porcentagem de ácidos graxos , que contribuem para a manutenção dos níveis adequados de lipoproteínas do tipo . Essas lipoproteínas ajudam a eliminar o excesso de colesterol do sangue e a prevenir a obstrução de vasos sanguíneos. As lacunas do texto são preenchidas, respectivamente, por:',null,'{"original": ["/unesp-2024/q68-1.png"], "support": ["/unesp-2024/tabela-periodica.png"]}','["Y – insaturados – LDL.", "X – saturados – LDL.", "Y – saturados – HDL.", "X – insaturados – HDL.", "Y – insaturados – HDL."]'::jsonb,'E',null from public.exams where slug='unesp-2024-fase1' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,69,'Conhecimentos Gerais','O exame de diagnóstico por imagem denominado PET-Scan (sigla em inglês para Tomografia por Emissão de Pósitrons) utiliza como emissor de pósitrons o radionuclídeo 18F. Ao emitir um pósitron, esse radionuclídeo transforma-se no isótopo 18O, cujo número de prótons e número de nêutrons são, respectivamente, iguais a',null,'{"original": ["/unesp-2024/q69-1.png"], "support": ["/unesp-2024/tabela-periodica.png"]}','["8 e 10.", "9 e 10.", "8 e 9.", "10 e 8.", "10 e 9."]'::jsonb,'A',null from public.exams where slug='unesp-2024-fase1' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,70,'Conhecimentos Gerais','Um produto químico sob forma de aerossol, empregado para lubrificar e soltar peças travadas, apresenta em sua embalagem os seguintes símbolos (pictogramas): (https://echa.europa.eu) Esses símbolos indicam que o produto deve ser armazenado em local',null,'{"original": ["/unesp-2024/q70-1.png"], "support": ["/unesp-2024/tabela-periodica.png"]}','["aquecido, longe do fogo, e utilizado em ambiente venti- lado.", "fresco, longe do fogo, e utilizado em ambiente fechado.", "fresco, perto do fogo, e utilizado em ambiente ventilado.", "aquecido, perto de fontes de calor, e utilizado em am- biente fechado.", "fresco, longe do fogo, e utilizado em ambiente ventilado."]'::jsonb,'E',null from public.exams where slug='unesp-2024-fase1' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,71,'Conhecimentos Gerais','O sistema Li/MnO2 é o exemplo mais representativo das pilhas primárias (de uso único) de lítio. (www.smartkits.com.br) Essas pilhas empregam eletrólitos dissolvidos em solventes não aquosos, em recipientes selados. O processo de descarga dessa pilha envolve a reação 4Li + MnO2 2Li2O + Mn Essa pilha fornece uma diferença de potencial (voltagem) em torno de 3,0 V à temperatura ambiente, mas mostra excelente desempenho em temperaturas superiores. A grande vantagem das pilhas à base de lítio é a ausência de metais pesados reconhecidamente danosos ao meio ambiente, como mercúrio, cádmio e chumbo. Porém, os perigos relativos à pilha Li/MnO2 são de outra natureza, estando relacionados ao seu descarte e reciclagem. Após a corrosão do invólucro externo, é liberado o solvente não aquoso, inflamável e tóxico. O lítio metálico não reagido, em contato com água e umidade do ar, desprende calor e gás inflamável (hidrogênio), podendo levar à ignição do produto descartado. Por isso, a presença de voltagem residual nesse resíduo é um problema, pois significa a presença de lítio metálico. As características listadas para a pilha de lítio tornam a disposição final inadequada e até mesmo a reciclagem uma operação de risco, pela possibilidade de fogo e explosão. (Jéssica Frontino Paulino et al. “Processamento de pilhas Li/MnO2 usadas”. Quim. Nova, vol. 30, 2007. Adaptado.) Para tornar a reciclagem dessa pilha mais segura, o ideal seria o seu descarregamento completo antes do descarte, evitando assim a',null,'{"original": ["/unesp-2024/q71-1.png"], "support": ["/unesp-2024/tabela-periodica.png"]}','["evaporação do solvente inflamável.", "redução do lítio metálico pelo oxigênio do ar.", "reação do óxido de lítio com a água.", "oxidação do lítio metálico pela água.", "interação da umidade do ar com o solvente inflamável."]'::jsonb,'D',null from public.exams where slug='unesp-2024-fase1' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,72,'Conhecimentos Gerais','A montagem de laboratório ilustrada na figura destina-se à coleta e medida do volume de produto gasoso gerado numa reação química. Em um experimento, envolvendo a produção de dióxido de carbono gasoso, CO2 (g), a partir da reação entre carbonato de cálcio, CaCO3 (s), e solução aquosa diluída de ácido clorídrico, HCl (aq), o líquido empregado para a coleta do gás foi a água acidulada. Um comprimido de CaCO3 foi triturado e uma porção do pó resultante foi colocada no erlenmeyer da montagem e posta para reagir com solução de HCl, adicionada a partir da seringa da montagem. Após a reação, o produto gasoso coletado no cilindro graduado teve seu volume determinado, sendo igual a 30 mL. Sabe-se que o produto gasoso recolhido é uma mistura de dióxido de carbono gasoso e vapor de água. Considerando que o experimento foi realizado sob pressão atmosférica de 726,7 mmHg e temperatura de 27 ºC, que a pressão de vapor da água a 27 ºC é igual a 26,7 mmHg e que a constante universal dos gases, R, é igual a 62,3 mmHg · L · mol–1 · K–1, a massa de carbonato de cálcio que reagiu na produção de dióxido de carbono gasoso foi de, aproximadamente,',null,'{"original": ["/unesp-2024/q72-1.png"], "support": ["/unesp-2024/tabela-periodica.png"]}','["1,0 g.", "0,001 g.", "0,1 g.", "0,01 g.", "10 g."]'::jsonb,'C',null from public.exams where slug='unesp-2024-fase1' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,73,'Conhecimentos Gerais','Analise a tabela, que apresenta valores da entalpia padrão de combustão completa (∆cH0) de três substâncias diferentes. ∆cH0 de Produtos da combustão Substância Fórmula combustão completa completa (kJ/mol) Ácido acético C2H4O2 (l) CO2 (g) e H2O (l) – 874 C Carbono CO2 (g) – 394 (s,grafita) Hidrogênio H2 (g) H2O (l) – 286 A partir desses valores de entalpia de combustão, é possível calcular a entalpia de formação do ácido acético, que é, em kJ/mol, igual a',null,'{"original": ["/unesp-2024/q73-1.png"], "support": ["/unesp-2024/tabela-periodica.png"]}','["– 486.", "+ 1 052.", "– 1 554.", "– 296.", "+ 19,4."]'::jsonb,'A',null from public.exams where slug='unesp-2024-fase1' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,74,'Conhecimentos Gerais','Água de cal é o nome dado à solução aquosa saturada de cal hidratada [hidróxido de cálcio, Ca(OH)2]. A concentração dessa solução saturada a 20 ºC é de 1,7 g/L. A partir desse dado, estima-se que o valor da constante do produto de solubilidade em água (Kps) nessa temperatura é próximo de',null,'{"original": ["/unesp-2024/q74-1.png"], "support": ["/unesp-2024/tabela-periodica.png"]}','["8 × 10– 6.", "4 × 10– 6.", "5 × 10– 7.", "8 × 10– 4.", "5 × 10– 5."]'::jsonb,'E',null from public.exams where slug='unesp-2024-fase1' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,75,'Conhecimentos Gerais','Uma das etapas da fermentação láctea consiste na transformação de ácido pirúvico em ácido láctico, pela reação representada pela equação: Na transformação de ácido pirúvico em ácido láctico ocorre do grupo de um composto opticamente , formando um composto opticamente . As lacunas do texto são preenchidas, respectivamente, por:',null,'{"original": ["/unesp-2024/q75-1.png"], "support": ["/unesp-2024/tabela-periodica.png"]}','["redução – carbonila – ativo – inativo.", "redução – carbonila – inativo – ativo.", "redução – carboxila – inativo – ativo.", "oxidação – carbonila – inativo – ativo.", "oxidação – carboxila – ativo – inativo."]'::jsonb,'B',null from public.exams where slug='unesp-2024-fase1' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,76,'Conhecimentos Gerais','Uma pessoa estava parada com seu veículo em um semáforo. Quando a luz verde do semáforo se acendeu, o veículo partiu e o movimento realizado até o seu destino pode ser dividido em quatro trechos: Trecho 1: veículo em movimento acelerado; Trecho 2: veículo em movimento uniforme; Trecho 3: percebendo que havia passado do endereço para onde ia, a pessoa freou o veículo até parar, e inverteu o sentido de seu movimento, com a mes- ma aceleração escalar com que havia freado; Trecho 4: nova frenagem, chegando ao seu destino, onde parou o veículo. Os três gráficos, I, II e III, mostram como variaram, em função do tempo, três grandezas escalares associadas ao movimento desse veículo, sem identificá-las, nos quatro trechos descritos. Sabendo que, enquanto se movia nesse trajeto, o veículo só esteve em movimento uniforme ou em movimento uniformemente variado, os gráficos I, II e III representam, respectivamente, as grandezas',null,'{"original": ["/unesp-2024/q76-1.png"], "support": ["/unesp-2024/tabela-periodica.png"]}','["posição, aceleração e velocidade.", "velocidade, aceleração e posição.", "velocidade, posição e aceleração.", "aceleração, posição e velocidade.", "aceleração, velocidade e posição."]'::jsonb,'D',null from public.exams where slug='unesp-2024-fase1' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,77,'Conhecimentos Gerais','A figura 1 representa uma molécula de DNA, que se assemelha a uma escada contorcida, isto é, tem o formato de uma dupla hélice. Analisado quimicamente, o DNA apresenta duas fitas complementares unidas por ligações existentes entre os pares de bases nitrogenadas, que podem ser adenina, citosina, timina ou guanina. Figura 1 (www.biologianet.com. Adaptado.) Considere que as duas bases nitrogenadas, B1 e B2, representadas na figura 2 por suas fórmulas estruturais, sejam ligadas uma à outra apenas pelas ações das forças elétricas F1, F2, F3 e F4 decorrentes das combinações O H – N e N – H N, mostradas em destaque, e que essas combinações sejam paralelas entre si. Figura 2 (Hugh D. Young e Roger A. Freedman. Física III. Eletromagnetismo, 2016. Adaptado.) Sabendo que as intensidades das forças são F1 = 8,0 × 10– 9 N, F2 = 3,0 × 10– 9 N, F3 = 2,6 × 10– 9 N e F4 = 6,4 × 10– 9 N, e considerando os possíveis pareamentos entre as bases nitrogenadas no DNA, as bases B1 e B2 são, respectivamente,',null,'{"original": ["/unesp-2024/q77-1.png"], "support": ["/unesp-2024/tabela-periodica.png"]}','["guanina e timina, e a intensidade da força elétrica resul- tante que B2 exerce em B1 é 8,8 × 10– 9 N.", "citosina e adenina, e a intensidade da força elétrica resul- tante que B2 exerce em B1 é 2,0 × 10– 9 N.", "timina e adenina, e a intensidade da força elétrica resul- tante que B2 exerce em B1 é 8,8 × 10– 9 N.", "timina e adenina, e a intensidade da força elétrica resul- tante que B2 exerce em B1 é 2,0 × 10– 8 N.", "citosina e guanina, e a intensidade da força elétrica resul- tante que B2 exerce em B1 é 1,2 × 10– 9 N."]'::jsonb,'C',null from public.exams where slug='unesp-2024-fase1' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,78,'Conhecimentos Gerais','Em uma brincadeira, uma pessoa coloca um copo com a boca para baixo, encostada na superfície parada da água de uma piscina e, cuidadosamente, o afunda 2,5 m abaixo da superfície da água, onde mantém o copo em repouso, ainda de boca para baixo, com um pouco de ar aprisionado em seu interior e com um pouco de água que entrou no copo. A figura mostra o copo nessas duas posições. fora de escala Considere o ar um gás ideal e os valores para a densidade da água da piscina, 105 Pa para a pressão atmosférica local e para a aceleração da gravidade. Sendo V1 o volume ocupado pelo ar no copo na posição inicial, V2 o volume ocupado pelo ar no copo na posição final, e considerando a temperatura do ar dentro do copo constante nesse processo, o valor da razão é',null,'{"original": ["/unesp-2024/q78-1.png"], "support": ["/unesp-2024/tabela-periodica.png"]}','["0,50.", "0,80.", "0,75.", "0,25.", "0,40."]'::jsonb,'B',null from public.exams where slug='unesp-2024-fase1' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,79,'Conhecimentos Gerais','A escala Brix, com valores expressos em ºBx (graus brix), é uma escala numérica que indica a quantidade de sólidos solúveis em uma solução de sacarose. Essa escala é utilizada na indústria de alimentos para medir a porcentagem aproximada de açúcares em sucos de fruta, vinhos, bebidas carbonatadas etc. Uma solução de 25 ºBx, por exemplo, tem 25 gramas de açúcar de sacarose por 100 gramas da solução. O gráfico mostra a relação entre a escala Brix e o índice de refração absoluto de uma solução de sacarose. (www.omega.com. Adaptado.) Considere um raio de luz monocromática que, propagando-se pelo ar, incide na superfície que separa o ar de uma solução de sacarose de 40 ºBx. Adotando c = 3 × 108 m/s, quando esse raio refratar-se para a solução de sacarose, terá velocidade de propagação de, aproximadamente,',null,'{"original": ["/unesp-2024/q79-1.png"], "support": ["/unesp-2024/tabela-periodica.png"]}','["1,0 × 108 m/s.", "2,8 × 108 m/s.", "2,1 × 108 m/s.", "1,2 × 108 m/s.", "0,8 × 108 m/s."]'::jsonb,'C',null from public.exams where slug='unesp-2024-fase1' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,80,'Conhecimentos Gerais','A icterícia, condição bastante comum em recém-nascidos, é caracterizada pela cor amarelada da pele. Esse problema relaciona-se à dificuldade do fígado para metabolizar a bilirrubina, um pigmento gerado pelo metabolismo das células vermelhas do sangue. A principal terapia em uso para icterícia é a fototerapia, com a exposição do recém-nascido a uma fonte luminosa. Devido às propriedades da bilirrubina e da pele, a luz mais efetiva para esse tratamento é a com comprimentos de onda predominantemente entre 425 nm e 475 nm, no espectro da cor azul. Luzes de outras cores, como a verde, têm espectro de emissão fora do espectro de absorção da molécula de bilirrubina. Já a luz ultravioleta emitida pelas lâmpadas de fototerapia é praticamente absorvida em sua totalidade pelo vidro da lâmpada e pela cobertura da unidade de fototerapia. (Scientia Medica, v. 15, abril/junho de 2005. Adaptado.) A figura mostra a curva de absorção da bilirrubina em função do comprimento de onda da luz. (www.sarda.org.ar. Adaptado.) Adotando-se c = 3 × 108 m/s, sabendo que 1 nm = 10– 9 m e de acordo com as informações do texto e da figura, tem-se que',null,'{"original": ["/unesp-2024/q80-1.png"], "support": ["/unesp-2024/tabela-periodica.png"]}','["as cores com frequências entre 0,425 Hz e 0,475 Hz são mais efetivas no tratamento de fototerapia para a icterícia.", "as cores com comprimentos de onda maiores do que os da cor verde são as mais absorvidas pela bilirrubina.", "a luz ultravioleta, por ter frequência menor do que a luz azul, não é efetiva no tratamento da icterícia.", "a cor com frequência aproximada de 6,5 × 1014 Hz é a mais efetiva no tratamento da icterícia.", "cores de frequências maiores do que a da cor verde não são absorvidas pela molécula da bilirrubina."]'::jsonb,'D',null from public.exams where slug='unesp-2024-fase1' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,81,'Conhecimentos Gerais','A imagem, produzida por um microscópio eletrônico, mostra uma seção transversal de uma fibra nervosa responsável pela transmissão de informações por meio de sinais elétricos. Essa fibra é composta pelo axônio, região central, envolvida pela mielina, uma substância gordurosa. (Hugh D. Young e Roger A. Freedman. Física III. Eletromagnetismo, 2016.) Sabendo que a resistividade elétrica da mielina é muito maior do que a resistividade elétrica do axônio, um sinal elétrico transmitido por essa fibra nervosa',null,'{"original": ["/unesp-2024/q81-1.png"], "support": ["/unesp-2024/tabela-periodica.png"]}','["mantém-se confinado no axônio, o que contribui para um aumento na velocidade de transmissão da informação.", "mantém-se confinado na mielina, o que contribui para uma diminuição na velocidade de transmissão da informação.", "mantém-se confinado no axônio, o que contribui para uma diminuição na velocidade de transmissão da informação.", "mantém-se confinado na mielina, o que contribui para um aumento na velocidade de transmissão da informação.", "distribui-se igualmente pela mielina e pelo axônio, o que contribui para um aumento na velocidade de transmissão da informação."]'::jsonb,'A',null from public.exams where slug='unesp-2024-fase1' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,82,'Conhecimentos Gerais','Alguns peixes, como os tubarões, orientam-se sentindo o campo magnético da Terra. Como cada local na Terra tem uma assinatura magnética diferente, supõem-se que esses peixes possam guardar no cérebro algum tipo de mapa magnético que os informa sobre onde estão. Para verificar essa suposição, foi realizado um experimento colocando tubarões em um tanque cercado por um cubo envolto em fios de cobre, pelos quais fez-se passar corrente elétrica. Essa corrente modificou o campo magnético da região, desorientando os tubarões. (www.nationalgeographicbrasil.com. Adaptado.) Suponha que a figura, fora de escala, represente uma das faces do cubo que cercou o tanque em que esse experimento foi realizado, envolvido por um fio de cobre com o formato de um solenoide, percorrido por uma corrente elétrica contínua (i) no sentido indicado. Considere que um tubarão esteja nadando ao longo do eixo longitudinal do solenoide, sujeito, simultaneamente, ao campo magnético criado pela Terra na região, , indicado na figura, e ao campo magnético criado pela corrente que circula pelo solenoide. Considere que esteja contido no plano da figura, que represente um vetor saindo do plano desta folha e que represente um vetor entrando no plano desta folha. A representação do campo magnético sentido pelo tubarão, devido aos efeitos simultâneos do campo magnético terrestre e da corrente que circula pelo solenoide, é:',null,'{"original": ["/unesp-2024/q82-1.png"], "support": ["/unesp-2024/tabela-periodica.png"]}','["Alternativa A, conforme o caderno original.", "Alternativa B, conforme o caderno original.", "Alternativa C, conforme o caderno original.", "Alternativa D, conforme o caderno original.", "Alternativa E, conforme o caderno original."]'::jsonb,'B',null from public.exams where slug='unesp-2024-fase1' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,83,'Conhecimentos Gerais','Analise o gráfico, que contém dados de matrículas no ensino superior presencial das 27 unidades da nossa Federação. Considere que essa rede de ensino superior presencial distribui-se apenas em privada ou pública. Razão, por unidade da Federação, entre o número de matrículas no ensino superior privado e o número de matrículas no ensino superior público – Brasil 2021 (“Censo da educação superior 2021”. https://inep.gov.br, 2022. Adaptado.) A análise do gráfico revela que o número de unidades da Federação com 60% ou mais de matrículas no ensino superior presencial sendo da rede privada é igual a',null,'{"original": ["/unesp-2024/q83-1.png"], "support": ["/unesp-2024/tabela-periodica.png"]}','["10.", "13.", "7.", "19.", "12."]'::jsonb,'E',null from public.exams where slug='unesp-2024-fase1' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,84,'Conhecimentos Gerais','Um trapézio retângulo ABCD foi dividido em um paralelogramo EBCF, um triângulo retângulo EFG e um retângulo AEGD de áreas denotadas por S1, S2 e S3, respectivamente. O trapézio, representado no plano cartesiano, mostra que os vértices dos três polígonos estão perfeitamente situados na interseção de linhas da malha quadriculada. A relação entre as três áreas mencionadas é:',null,'{"original": ["/unesp-2024/q84-1.png"], "support": ["/unesp-2024/tabela-periodica.png"]}','["25 · S1 = 12 · S2 = 10 · S3", "2 · S1 = S2 = S3", "5 · S1 = 2 · S2 = 2 · S3", "12 · S1 = 5 · S2 = 5 · S3", "25 · S1 = 10 · S2 = 12 · S3"]'::jsonb,'C',null from public.exams where slug='unesp-2024-fase1' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,85,'Conhecimentos Gerais','Seja a equação quadrática nx2 – x + 1 = 0, em que n é uma constante real, com duas raízes reais positivas e distintas. Assim, os valores de n que satisfazem essas condições são tais que:',null,'{"original": ["/unesp-2024/q85-1.png"], "support": ["/unesp-2024/tabela-periodica.png"]}','["Alternativa A, conforme o caderno original.", "Alternativa B, conforme o caderno original.", "Alternativa C, conforme o caderno original.", "Alternativa D, conforme o caderno original.", "Alternativa E, conforme o caderno original."]'::jsonb,'A',null from public.exams where slug='unesp-2024-fase1' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,86,'Conhecimentos Gerais','Uma placa quadrada de massa 2 kg e lado 2 e uma placa retangular de massa 3 kg e lados 2 por 4 possuem suas respectivas massas homogeneamente distribuídas, espessuras desprezíveis e estão dispostas, uma a uma, em um plano cartesiano de eixos ortogonais. Nesse plano cartesiano, as coordenadas do centro de massa C do conjunto das duas placas são calculadas da seguinte forma: Acrescentando-se nesse plano uma placa circular também de espessura desprezível, com centro (2, 1), raio 1 e massa 3 kg, o centro de massa do novo conjunto, agora com as três placas, passará a ter coordenadas',null,'{"original": ["/unesp-2024/q86-1.png"], "support": ["/unesp-2024/tabela-periodica.png"]}','["(4,75; 3).", "(3,5; 2,25).", "(6; 3,5).", "(5; 3).", "(6; 4)."]'::jsonb,'D',null from public.exams where slug='unesp-2024-fase1' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,87,'Conhecimentos Gerais','Ana somou dois números distintos sorteados ao acaso do conjunto {8,9,10}. Beto multiplicou dois números distintos sorteados ao acaso do conjunto {3,5,6}. A probabilidade de que o resultado obtido na conta de Ana tenha sido maior ou igual ao obtido na conta de Beto é igual a:',null,'{"original": ["/unesp-2024/q87-1.png"], "support": ["/unesp-2024/tabela-periodica.png"]}','["Alternativa A, conforme o caderno original.", "Alternativa B, conforme o caderno original.", "Alternativa C, conforme o caderno original.", "Alternativa D, conforme o caderno original.", "Alternativa E, conforme o caderno original."]'::jsonb,'E',null from public.exams where slug='unesp-2024-fase1' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,88,'Conhecimentos Gerais','Três insetos da mesma espécie foram introduzidos em um ambiente no instante zero. Sete meses depois, constatou-se que havia uma população de 18 000 desses insetos no ambiente. Considere que o modelo de crescimento da população desses insetos é exponencial, dado por , em que t e u são constantes reais e f(x) é a população de insetos após x meses do início da cultura. Observe o gráfico da função , em que x é um número inteiro maior do que 2, e que apresenta os valores aproximados das ordenadas de alguns de seus pontos. Com os dados fornecidos, segue que t + u é, aproximadamente,',null,'{"original": ["/unesp-2024/q88-1.png"], "support": ["/unesp-2024/tabela-periodica.png"]}','["5,09.", "10,26.", "6,47.", "7,62.", "7,26."]'::jsonb,'C',null from public.exams where slug='unesp-2024-fase1' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,89,'Conhecimentos Gerais','A figura indica o projeto de uma casa, sustentada por dois pilares e com rampa retilínea, de inclinação α em relação à horizontal, direcionando-se ao subsolo da casa. Todas as medidas indicadas na figura estão em metros. Dados: Considerando que os dois pilares são retilíneos e perpendiculares ao eixo x, a medida do pilar menor, em metros, e o intervalo angular ao qual α pertence são, respectivamente:',null,'{"original": ["/unesp-2024/q89-1.png"], "support": ["/unesp-2024/tabela-periodica.png"]}','["Alternativa A, conforme o caderno original.", "Alternativa B, conforme o caderno original.", "Alternativa C, conforme o caderno original.", "Alternativa D, conforme o caderno original.", "Alternativa E, conforme o caderno original."]'::jsonb,'B',null from public.exams where slug='unesp-2024-fase1' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,90,'Conhecimentos Gerais','O ChatGPT é uma ferramenta computacional de inteligência artificial que, entre outras aplicações, pode tentar resolver alguns problemas matemáticos. O problema matemático a seguir foi submetido ao ChatGPT. (https://chat.openai.com. Adaptado.) A ferramenta apresentou como solução do problema o número 13246, o que não está correto. Considerando que essa solução incorreta tenha relação com uma leitura imprecisa do texto pelo ChatGPT, tal imprecisão deve-se ao fato de a ferramenta ter ignorado',null,'{"original": ["/unesp-2024/q90-1.png"], "support": ["/unesp-2024/tabela-periodica.png"]}','["a condição de que os algarismos sejam distintos.", "a forma imperativa do verbo “escrever”.", "o trecho “sem usar o zero”.", "o trecho “da direita para a esquerda”.", "o trecho “da esquerda para a direita”."]'::jsonb,'D',null from public.exams where slug='unesp-2024-fase1' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
